const crypto = require('node:crypto')
const fs = require('node:fs')
const path = require('node:path')

const roles = ['Super Admin','Teacher','Parent','Student','Stakeholder','Finance Officer']
const permissionNames = ['dashboard.read','school.manage','users.manage','students.read','students.manage','classes.manage','academics.read','academics.manage','finance.read','finance.manage','attendance.read','attendance.manage','stakeholders.read','stakeholders.manage','communication.read','communication.manage','resources.read','resources.manage','reports.read','backups.manage']
const uuid = () => crypto.randomUUID()
const now = () => new Date().toISOString()
const hash = (s) => crypto.createHash('sha256').update(s).digest('hex')
const text = (value, label, max = 200) => { if (typeof value !== 'string' || !value.trim() || value.length > max) throw new Error(`${label} is required (maximum ${max} characters).`); return value.trim() }
const money = (value, label = 'Amount') => { const number = Number(value); if (!Number.isFinite(number) || number <= 0 || number > 1000000000) throw new Error(`${label} must be a positive amount.`); return Math.round(number * 100) }

function createServices(db, runtime) {
  const app = runtime || require('electron').app
  const atomic = db.transaction((fn) => fn())
  const seed = db.transaction(() => {
    roles.forEach((name, i) => db.prepare('INSERT OR IGNORE INTO roles(id,key,name,system_role) VALUES(?,?,?,1)').run(i + 1, name.toLowerCase().replaceAll(' ', '_'), name))
    permissionNames.forEach((name) => db.prepare('INSERT OR IGNORE INTO permissions(key,description) VALUES(?,?)').run(name, name.replaceAll('.', ' ')))
    const permission = Object.fromEntries(db.prepare('SELECT id,key FROM permissions').all().map((p) => [p.key,p.id]))
    const mapping = {
      'Super Admin': permissionNames,
      'Teacher': ['dashboard.read','students.read','academics.read','academics.manage','attendance.read','attendance.manage','communication.read','communication.manage','resources.read','resources.manage'],
      'Parent': ['dashboard.read','students.read','academics.read','finance.read','attendance.read','communication.read','communication.manage','resources.read'],
      'Student': ['dashboard.read','students.read','academics.read','attendance.read','communication.read','resources.read'],
      'Stakeholder': ['dashboard.read','communication.read'],
      'Finance Officer': ['dashboard.read','students.read','finance.read','finance.manage','reports.read'],
    }
    for (const [role, keys] of Object.entries(mapping)) for (const key of keys) db.prepare('INSERT OR IGNORE INTO role_permissions(role_id,permission_id) VALUES((SELECT id FROM roles WHERE name=?),?)').run(role, permission[key])
    // Recover a first-install database if its only account was created without
    // the initial Super Admin role link. Never elevate an account in a multi-user DB.
    const accountCount = db.prepare('SELECT COUNT(*) count FROM users').get().count
    if (accountCount === 1) {
      const initialUser = db.prepare('SELECT id FROM users LIMIT 1').get()
      const alreadyAdmin = initialUser && db.prepare("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.name='Super Admin'").get(initialUser.id)
      if (initialUser && !alreadyAdmin) {
        db.prepare("INSERT INTO user_roles(user_id,role_id) VALUES(?,(SELECT id FROM roles WHERE name='Super Admin'))").run(initialUser.id)
        db.prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?)').run(initialUser.id,'initial_admin_role_recovered','users',initialUser.id,JSON.stringify({reason:'single-user database had no recognized Super Admin role'}))
      }
    }
    db.prepare("INSERT OR IGNORE INTO app_settings(key,value_json) VALUES('admission-sequence','0'),('receipt-sequence','0')").run()
  })
  seed()

  function actor(token, permission) {
    if (typeof token !== 'string' || token.length < 20) throw new Error('Please sign in to continue.')
    const session = db.prepare('SELECT u.id,u.username,u.active,s.expires_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?').get(hash(token))
    if (!session || !session.active || new Date(session.expires_at) < new Date()) throw new Error('Your session has expired. Please sign in again.')
    const user = { id: session.id, username: session.username }
    const permissions = db.prepare('SELECT DISTINCT p.key FROM user_roles ur JOIN role_permissions rp ON rp.role_id=ur.role_id JOIN permissions p ON p.id=rp.permission_id WHERE ur.user_id=?').all(user.id).map((p) => p.key)
    if (permission && !permissions.includes(permission)) throw new Error('You do not have permission to perform this action.')
    user.permissions = permissions
    user.roles = db.prepare('SELECT r.name FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=?').all(user.id).map((r) => r.name)
    return user
  }
  function audit(userId, action, entity, id, details = {}) { db.prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details_json) VALUES(?,?,?,?,?)').run(userId || null, action, entity, id == null ? null : String(id), JSON.stringify(details)) }
  function nextSetting(key, prefix) {
    const row = db.prepare('SELECT value_json FROM app_settings WHERE key=?').get(key)
    const next = Number(row?.value_json || 0) + 1
    db.prepare('INSERT INTO app_settings(key,value_json,updated_at) VALUES(?,?,CURRENT_TIMESTAMP) ON CONFLICT(key) DO UPDATE SET value_json=excluded.value_json,updated_at=CURRENT_TIMESTAMP').run(key, String(next))
    return `${prefix}-${new Date().getFullYear()}-${String(next).padStart(5,'0')}`
  }
  function password(value) {
    if (typeof value !== 'string' || value.length < 10 || value.length > 200) throw new Error('Use a password between 10 and 200 characters.')
    const salt = crypto.randomBytes(16).toString('hex')
    const digest = crypto.scryptSync(value, salt, 64).toString('hex')
    return { salt, digest }
  }
  function safeUser(id) {
    const u = db.prepare('SELECT id,username,email,active,created_at FROM users WHERE id=?').get(id)
    if (!u) return null
    return { ...u, roles: db.prepare('SELECT r.name FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=?').all(id).map((x) => x.name), permissions: db.prepare('SELECT DISTINCT p.key FROM user_roles ur JOIN role_permissions rp ON rp.role_id=ur.role_id JOIN permissions p ON p.id=rp.permission_id WHERE ur.user_id=?').all(id).map((x)=>x.key) }
  }
  const auth = {
    needsSetup: () => db.prepare('SELECT COUNT(*) n FROM users').get().n === 0,
    createFirstAdmin(input) {
      return atomic(() => {
        if (!auth.needsSetup()) throw new Error('Initial administrator setup has already been completed.')
        const username = text(input?.username,'Username',60)
        const email = input?.email ? text(input.email,'Email',254) : null
        if (email && !/^\S+@\S+\.\S+$/.test(email)) throw new Error('Enter a valid email address.')
        const secret = password(input?.password)
        const id = uuid()
        db.prepare('INSERT INTO users(id,username,email,password_hash,password_salt,must_change_password) VALUES(?,?,?,?,?,0)').run(id,username,email,secret.digest,secret.salt)
        db.prepare("INSERT INTO user_roles(user_id,role_id) VALUES(?,(SELECT id FROM roles WHERE name='Super Admin'))").run(id)
        audit(id,'initial_admin_created','users',id)
        return { token: auth.createSession(id), user: safeUser(id) }
      })
    },
    createSession(userId) {
      const token = crypto.randomBytes(32).toString('base64url')
      db.prepare('INSERT INTO sessions(token_hash,user_id,expires_at) VALUES(?,?,?)').run(hash(token),userId,new Date(Date.now()+12*60*60*1000).toISOString())
      db.prepare('UPDATE users SET last_login_at=?,updated_at=? WHERE id=?').run(now(),now(),userId)
      return token
    },
    login(input) {
      const row = db.prepare('SELECT * FROM users WHERE username=? COLLATE NOCASE AND active=1').get(text(input?.username,'Username',254))
      if (!row) throw new Error('Username or password is incorrect.')
      const provided = crypto.scryptSync(String(input?.password || ''),row.password_salt,64)
      if (!crypto.timingSafeEqual(provided,Buffer.from(row.password_hash,'hex'))) throw new Error('Username or password is incorrect.')
      const token = auth.createSession(row.id)
      return { token,user:safeUser(row.id) }
    },
    logout(token) { db.prepare('DELETE FROM sessions WHERE token_hash=?').run(hash(String(token || ''))); return true },
    me(token) { return safeUser(actor(token).id) },
  }

  const school = {
    get(token) { actor(token,'dashboard.read'); const record=db.prepare('SELECT * FROM schools WHERE id=1').get();if(record?.logo_path&&fs.existsSync(record.logo_path)){try{const ext=path.extname(record.logo_path).toLowerCase();const mime=ext==='.png'?'image/png':ext==='.webp'?'image/webp':'image/jpeg';record.logo_data_url=`data:${mime};base64,${fs.readFileSync(record.logo_path).toString('base64')}`}catch{record.logo_data_url=null}}return record },
    update(token,input) { const user=actor(token,'school.manage'); const data={name:text(input.name,'School name'),code:input.code||null,address:input.address||null,phone:input.phone||null,email:input.email||null,motto:input.motto||null}; db.prepare('UPDATE schools SET name=@name,code=@code,address=@address,phone=@phone,email=@email,motto=@motto,updated_at=CURRENT_TIMESTAMP WHERE id=1').run(data);audit(user.id,'school_updated','schools',1);return school.get(token) },
    setLogo(token,source){const user=actor(token,'school.manage');if(!source||!path.isAbsolute(source)||!fs.existsSync(source))throw new Error('Choose a valid school logo image.');const ext=path.extname(source).toLowerCase();if(!['.png','.jpg','.jpeg','.webp'].includes(ext))throw new Error('School logo must be PNG, JPG, or WebP.');const stat=fs.statSync(source);if(stat.size>5*1024*1024)throw new Error('School logo must be smaller than 5 MB.');const dir=path.join(app.getPath('userData'),'branding');fs.mkdirSync(dir,{recursive:true});const target=path.join(dir,`school-logo${ext}`);fs.copyFileSync(source,target);db.prepare('UPDATE schools SET logo_path=?,updated_at=CURRENT_TIMESTAMP WHERE id=1').run(target);audit(user.id,'school_logo_updated','schools',1);return school.get(token)},
    academicData(token){actor(token,'dashboard.read');return{sessions:db.prepare('SELECT * FROM academic_sessions ORDER BY starts_on DESC').all(),terms:db.prepare('SELECT t.*,s.name session_name FROM terms t JOIN academic_sessions s ON s.id=t.session_id ORDER BY s.starts_on DESC,t.id').all()}},
    createSession(token,input){const user=actor(token,'school.manage');const name=text(input.name,'Academic session',40);const id=Number(atomic(()=>{if(input.active)db.prepare('UPDATE academic_sessions SET active=0').run();return db.prepare('INSERT INTO academic_sessions(name,starts_on,ends_on,active) VALUES(?,?,?,?)').run(name,input.startsOn||null,input.endsOn||null,input.active?1:0).lastInsertRowid}));audit(user.id,'academic_session_created','academic_sessions',id);return{id}},
    createTerm(token,input){const user=actor(token,'school.manage');const name=text(input.name,'Term',30);if(!['First Term','Second Term','Third Term'].includes(name))throw new Error('Choose First, Second, or Third Term.');const id=Number(atomic(()=>{if(input.active)db.prepare('UPDATE terms SET active=0 WHERE session_id=?').run(Number(input.sessionId));return db.prepare('INSERT INTO terms(session_id,name,starts_on,ends_on,active) VALUES(?,?,?,?,?)').run(Number(input.sessionId),name,input.startsOn||null,input.endsOn||null,input.active?1:0).lastInsertRowid}));audit(user.id,'academic_term_created','terms',id);return{id}},
    updateSession(token,id,input){const user=actor(token,'school.manage');const sessionId=Number(id);const existing=db.prepare('SELECT id FROM academic_sessions WHERE id=?').get(sessionId);if(!existing)throw new Error('Academic session not found.');const name=text(input.name,'Academic session',40);atomic(()=>{if(input.active)db.prepare('UPDATE academic_sessions SET active=0').run();db.prepare('UPDATE academic_sessions SET name=?,starts_on=?,ends_on=?,active=? WHERE id=?').run(name,input.startsOn||null,input.endsOn||null,input.active?1:0,sessionId)});audit(user.id,'academic_session_updated','academic_sessions',sessionId);return{id:sessionId}},
    updateTerm(token,id,input){const user=actor(token,'school.manage');const termId=Number(id);const existing=db.prepare('SELECT id FROM terms WHERE id=?').get(termId);if(!existing)throw new Error('Term not found.');const sessionId=Number(input.sessionId);if(!Number.isInteger(sessionId)||!db.prepare('SELECT id FROM academic_sessions WHERE id=?').get(sessionId))throw new Error('Choose a valid academic session.');const name=text(input.name,'Term',30);if(!['First Term','Second Term','Third Term'].includes(name))throw new Error('Choose First, Second, or Third Term.');atomic(()=>{if(input.active)db.prepare('UPDATE terms SET active=0 WHERE session_id=?').run(sessionId);db.prepare('UPDATE terms SET session_id=?,name=?,starts_on=?,ends_on=?,active=? WHERE id=?').run(sessionId,name,input.startsOn||null,input.endsOn||null,input.active?1:0,termId)});audit(user.id,'academic_term_updated','terms',termId);return{id:termId}},
  }

  const dashboard = { summary(token) {
    const user=actor(token,'dashboard.read')
    const portalOnly=user.roles.some(r=>['Parent','Student','Stakeholder'].includes(r))
    const isFinance=user.permissions.includes('finance.read')&&!user.roles.some(r=>['Parent','Student'].includes(r))
    let students,staff,parents,byClass=[]
    if(user.roles.includes('Parent')){students=db.prepare("SELECT COUNT(DISTINCT s.id) n FROM students s JOIN student_parents sp ON sp.student_id=s.id JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=? AND s.status='Active'").get(user.id).n;staff=0;parents=0}
    else if(user.roles.includes('Student')){students=db.prepare("SELECT COUNT(*) n FROM students s JOIN student_portal_link l ON l.student_id=s.id WHERE l.user_id=? AND s.status='Active'").get(user.id).n;staff=0;parents=0}
    else if(user.roles.includes('Teacher')){students=db.prepare("SELECT COUNT(DISTINCT s.id) n FROM students s JOIN teacher_assignments ta ON ta.class_arm_id=s.class_arm_id JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND s.status='Active'").get(user.id).n;staff=0;parents=0;byClass=db.prepare("SELECT c.name class_name,COUNT(DISTINCT s.id) total,SUM(CASE WHEN s.gender='Female' THEN 1 ELSE 0 END) girls,SUM(CASE WHEN s.gender='Male' THEN 1 ELSE 0 END) boys FROM classes c JOIN class_arms a ON a.class_id=c.id JOIN teacher_assignments ta ON ta.class_arm_id=a.id JOIN staff st ON st.id=ta.staff_id LEFT JOIN students s ON s.class_arm_id=a.id AND s.status='Active' WHERE st.user_id=? GROUP BY c.id ORDER BY c.sort_order,c.name").all(user.id)}
    else if(portalOnly){students=db.prepare("SELECT COUNT(*) n FROM stakeholder_registrations r JOIN stakeholder_schools s ON s.id=r.stakeholder_id WHERE s.user_id=?").get(user.id).n;staff=0;parents=0}
    else{students=db.prepare("SELECT COUNT(*) n FROM students WHERE status='Active'").get().n;staff=db.prepare('SELECT COUNT(*) n FROM staff WHERE active=1').get().n;parents=db.prepare('SELECT COUNT(*) n FROM parents').get().n;byClass=db.prepare("SELECT c.name class_name,COUNT(s.id) total,SUM(CASE WHEN s.gender='Female' THEN 1 ELSE 0 END) girls,SUM(CASE WHEN s.gender='Male' THEN 1 ELSE 0 END) boys FROM classes c LEFT JOIN class_arms a ON a.class_id=c.id LEFT JOIN students s ON s.class_arm_id=a.id AND s.status='Active' GROUP BY c.id ORDER BY c.sort_order,c.name").all()}
    const term=db.prepare('SELECT t.id,t.name,t.session_id,s.name session_name FROM terms t JOIN academic_sessions s ON s.id=t.session_id WHERE t.active=1 LIMIT 1').get()
    let feeData=null,recentPayments=[]
    if(isFinance){feeData=financeSummaryRows(term);const bounds=term?db.prepare('SELECT starts_on,ends_on FROM terms WHERE id=?').get(term.id):null;const expenditure=term?db.prepare("SELECT COALESCE(SUM(amount_kobo),0) amount FROM expenses WHERE spent_on>=COALESCE(?,date('now','start of year')) AND spent_on<=COALESCE(?,date('now'))").get(bounds?.starts_on||null,bounds?.ends_on||null).amount/100:db.prepare('SELECT COALESCE(SUM(amount_kobo),0) amount FROM expenses').get().amount/100;feeData={...feeData,expenditure,net:feeData.collected-expenditure};recentPayments=db.prepare('SELECT p.receipt_number,p.amount_kobo,p.paid_at,s.first_name||\' \'||s.surname student_name FROM payments p JOIN students s ON s.id=p.student_id WHERE p.status=\'Verified\' ORDER BY p.paid_at DESC LIMIT 6').all()}
    const recentActivities=user.permissions.includes('school.manage')?db.prepare('SELECT action,entity_type,details_json,created_at FROM audit_logs ORDER BY id DESC LIMIT 8').all().map(x=>({...x,details:JSON.parse(x.details_json)})):[]
    const teacherScope=user.roles.includes('Teacher')
    const performance=teacherScope?db.prepare("SELECT AVG(r.score) average_score,COUNT(DISTINCT r.student_id) students_assessed FROM results r JOIN students s ON s.id=r.student_id JOIN teacher_assignments ta ON ta.class_arm_id=s.class_arm_id JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND r.status='Approved'").get(user.id):portalOnly?{average_score:null,students_assessed:0}:db.prepare("SELECT AVG(score) average_score,COUNT(DISTINCT student_id) students_assessed FROM results WHERE status='Approved'").get()
    const studentPerformance=portalOnly?[]:(teacherScope?db.prepare("SELECT CASE WHEN avg_score>=80 THEN '80–100%' WHEN avg_score>=60 THEN '60–79%' WHEN avg_score>=40 THEN '40–59%' ELSE '0–39%' END band,COUNT(*) total FROM (SELECT r.student_id,AVG(r.score) avg_score FROM results r JOIN students s ON s.id=r.student_id JOIN teacher_assignments ta ON ta.class_arm_id=s.class_arm_id JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND r.status='Approved' GROUP BY r.student_id) GROUP BY band").all(user.id):db.prepare("SELECT CASE WHEN avg_score>=80 THEN '80–100%' WHEN avg_score>=60 THEN '60–79%' WHEN avg_score>=40 THEN '40–59%' ELSE '0–39%' END band,COUNT(*) total FROM (SELECT student_id,AVG(score) avg_score FROM results WHERE status='Approved' GROUP BY student_id) GROUP BY band").all())
    const classPerformance=portalOnly?[]:(teacherScope?db.prepare("SELECT c.name class_name,ROUND(AVG(r.score),1) average_score,COUNT(DISTINCT r.student_id) students_assessed FROM results r JOIN students s ON s.id=r.student_id JOIN class_arms a ON a.id=s.class_arm_id JOIN classes c ON c.id=a.class_id JOIN teacher_assignments ta ON ta.class_arm_id=a.id JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND r.status='Approved' GROUP BY c.id ORDER BY c.sort_order,c.name").all(user.id):db.prepare("SELECT c.name class_name,ROUND(AVG(r.score),1) average_score,COUNT(DISTINCT r.student_id) students_assessed FROM results r JOIN students s ON s.id=r.student_id JOIN class_arms a ON a.id=s.class_arm_id JOIN classes c ON c.id=a.class_id WHERE r.status='Approved' GROUP BY c.id ORDER BY c.sort_order,c.name").all())
    return {students,staff,parents,byClass,term:term||null,finance:feeData,recentPayments:recentPayments.map(p=>({...p,amount:p.amount_kobo/100})),recentActivities,performance,studentPerformance,classPerformance,roles:user.roles}
  } }

  const classes = {
    list(token) { const user=actor(token,'students.read');let scope='',params=[];if(user.roles.includes('Teacher')){scope='WHERE a.id IN (SELECT ta.class_arm_id FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=?)';params.push(user.id)}else if(user.roles.includes('Parent')){scope='WHERE a.id IN (SELECT s.class_arm_id FROM students s JOIN student_parents sp ON sp.student_id=s.id JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=?)';params.push(user.id)}else if(user.roles.includes('Student')){scope='WHERE a.id=(SELECT s.class_arm_id FROM students s JOIN student_portal_link l ON l.student_id=s.id WHERE l.user_id=?)';params.push(user.id)}return db.prepare(`SELECT c.id,c.name,c.level,c.sort_order,a.id class_arm_id,a.name arm_name,a.capacity,COUNT(s.id) student_count FROM classes c LEFT JOIN class_arms a ON a.class_id=c.id LEFT JOIN students s ON s.class_arm_id=a.id AND s.status='Active' ${scope} GROUP BY c.id,a.id ORDER BY c.sort_order,a.name`).all(...params) },
    create(token,input) { const user=actor(token,'classes.manage'); return atomic(()=>{const result=db.prepare('INSERT INTO classes(name,level,sort_order) VALUES(?,?,?)').run(text(input.name,'Class name',80),text(input.level,'School level',40),Number(input.sortOrder||0));const classId=Number(result.lastInsertRowid);const arms=Array.isArray(input.arms)?input.arms:[];for(const arm of arms)db.prepare('INSERT INTO class_arms(class_id,name,capacity) VALUES(?,?,?)').run(classId,text(arm.name,'Arm name',40),arm.capacity?Number(arm.capacity):null);audit(user.id,'class_created','classes',classId);return classes.list(token)}) },
    assignTeacher(token,input){const user=actor(token,'school.manage');const staff=db.prepare("SELECT id FROM staff WHERE id=? AND kind='Teacher' AND active=1").get(input.staffId);if(!staff)throw new Error('Active teacher record not found.');const arm=db.prepare('SELECT id FROM class_arms WHERE id=?').get(Number(input.classArmId));if(!arm)throw new Error('Class arm not found.');const subject=input.subjectId?Number(input.subjectId):null;if(subject&&!db.prepare('SELECT id FROM subjects WHERE id=?').get(subject))throw new Error('Subject not found.');const id=Number(db.prepare('INSERT INTO teacher_assignments(staff_id,class_arm_id,subject_id) VALUES(?,?,?)').run(staff.id,arm.id,subject).lastInsertRowid);audit(user.id,'teacher_assigned','teacher_assignments',id);return{id}},
    assignments(token){actor(token,'school.manage');return db.prepare('SELECT ta.id,ta.staff_id,ta.class_arm_id,ta.subject_id,st.first_name||\' \'||st.surname teacher_name,st.staff_number,c.name class_name,a.name arm_name,sub.name subject FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id JOIN class_arms a ON a.id=ta.class_arm_id JOIN classes c ON c.id=a.class_id LEFT JOIN subjects sub ON sub.id=ta.subject_id ORDER BY st.surname,c.sort_order,a.name,sub.name').all()},
    teachers(token){actor(token,'school.manage');return db.prepare("SELECT st.id staff_id,st.first_name,st.surname,st.staff_number,u.username,u.email FROM staff st JOIN users u ON u.id=st.user_id WHERE st.kind='Teacher' AND st.active=1 ORDER BY st.surname,st.first_name").all()},
    classSubjects(token){actor(token,'school.manage');return db.prepare('SELECT cs.id,cs.class_arm_id,c.name class_name,a.name arm_name,cs.subject_id,s.name subject FROM class_subjects cs JOIN class_arms a ON a.id=cs.class_arm_id JOIN classes c ON c.id=a.class_id JOIN subjects s ON s.id=cs.subject_id ORDER BY c.sort_order,a.name,s.name').all()},
    assignSubject(token,input){const user=actor(token,'school.manage');const arm=Number(input.classArmId),subject=Number(input.subjectId);if(!db.prepare('SELECT id FROM class_arms WHERE id=?').get(arm)||!db.prepare('SELECT id FROM subjects WHERE id=? AND active=1').get(subject))throw new Error('Choose an active class arm and subject.');const id=Number(db.prepare('INSERT INTO class_subjects(class_arm_id,subject_id) VALUES(?,?)').run(arm,subject).lastInsertRowid);audit(user.id,'subject_assigned','class_subjects',id);return{id}},
  }
  const students = {
    list(token,filter={}) {
      const user=actor(token,'students.read')
      let where=["s.status='Active'"], params=[]
      if(user.roles.includes('Teacher')){where.push('s.class_arm_id IN (SELECT class_arm_id FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=?)');params.push(user.id)}
      if(user.roles.includes('Parent')){where.push('s.id IN (SELECT student_id FROM student_parents sp JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=?)');params.push(user.id)}
      if(user.roles.includes('Student')){where.push('s.id=(SELECT student_id FROM student_portal_link WHERE user_id=?)');params.push(user.id)}
      if(filter.classArmId){where.push('s.class_arm_id=?');params.push(Number(filter.classArmId))}
      if(filter.search){where.push("(s.first_name||' '||s.middle_name||' '||s.surname LIKE ? OR s.admission_number LIKE ?)");params.push(`%${filter.search}%`,`%${filter.search}%`)}
      const cap=Math.max(1,Math.min(Number(filter.limit)||300,1000))
      return db.prepare(`SELECT s.id,s.admission_number,s.first_name,s.middle_name,s.surname,s.gender,s.date_of_birth,s.admission_date,s.class_arm_id,a.name arm_name,c.name class_name,c.level,s.status,(SELECT p.first_name||' '||p.surname FROM parents p JOIN student_parents sp ON sp.parent_id=p.id WHERE sp.student_id=s.id AND sp.primary_contact=1 LIMIT 1) parent_name,(SELECT p.phone FROM parents p JOIN student_parents sp ON sp.parent_id=p.id WHERE sp.student_id=s.id AND sp.primary_contact=1 LIMIT 1) parent_phone FROM students s JOIN class_arms a ON a.id=s.class_arm_id JOIN classes c ON c.id=a.class_id WHERE ${where.join(' AND ')} ORDER BY s.surname,s.first_name LIMIT ?`).all(...params,cap)
    },
    create(token,input) {
      const user=actor(token,'students.manage')
      return atomic(()=>{const id=uuid(),admission=nextSetting('admission-sequence','OSC');const first=text(input.firstName,'First name',80),surname=text(input.surname,'Surname',80);if(!['Female','Male','Other'].includes(input.gender))throw new Error('Select a valid gender.');const session=Number(input.sessionId);if(!db.prepare('SELECT id FROM academic_sessions WHERE id=?').get(session))throw new Error('Select a valid academic session.');if(!db.prepare('SELECT id FROM class_arms WHERE id=?').get(Number(input.classArmId)))throw new Error('Select a valid class and arm.');db.prepare('INSERT INTO students(id,admission_number,first_name,middle_name,surname,gender,date_of_birth,state_of_origin,lga,nationality,address,photograph_path,previous_school,admission_date,session_id,class_arm_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').run(id,admission,first,input.middleName||'',surname,input.gender,input.dateOfBirth||null,input.stateOfOrigin||null,input.lga||null,input.nationality||'Nigerian',input.address||null,input.photographPath||null,input.previousSchool||null,input.admissionDate||now().slice(0,10),session,Number(input.classArmId));if(input.parent?.firstName&&input.parent?.phone){const pId=uuid();db.prepare('INSERT INTO parents(id,first_name,surname,phone,email,address) VALUES(?,?,?,?,?,?)').run(pId,input.parent.firstName,input.parent.surname||'',input.parent.phone,input.parent.email||null,input.parent.address||null);db.prepare('INSERT INTO student_parents(student_id,parent_id,relationship,primary_contact) VALUES(?,?,?,1)').run(id,pId,input.parent.relationship||'Guardian')}audit(user.id,'student_registered','students',id,{admission_number:admission});return {id,admissionNumber:admission}})
    },
    update(token,id,input){const user=actor(token,'students.manage');const existing=db.prepare('SELECT id FROM students WHERE id=?').get(id);if(!existing)throw new Error('Student record not found.');if(input.classArmId!==undefined&&!db.prepare('SELECT id FROM class_arms WHERE id=?').get(Number(input.classArmId)))throw new Error('Choose a valid class and arm.');if(input.gender!==undefined&&!['Female','Male','Other'].includes(input.gender))throw new Error('Choose a valid gender.');if(input.photographPath){if(!path.isAbsolute(input.photographPath)||!fs.existsSync(input.photographPath))throw new Error('Choose a valid student photograph.');const ext=path.extname(input.photographPath).toLowerCase();if(!['.png','.jpg','.jpeg','.webp'].includes(ext))throw new Error('Student photograph must be PNG, JPG, or WebP.');if(fs.statSync(input.photographPath).size>5*1024*1024)throw new Error('Student photograph must be smaller than 5 MB.')}const fields={first_name:input.firstName,surname:input.surname,middle_name:input.middleName,gender:input.gender,class_arm_id:input.classArmId?Number(input.classArmId):undefined,date_of_birth:input.dateOfBirth,state_of_origin:input.stateOfOrigin,lga:input.lga,nationality:input.nationality,address:input.address,previous_school:input.previousSchool,admission_date:input.admissionDate,photograph_path:input.photographPath};for(const [key,value]of Object.entries(fields))if(value!==undefined)db.prepare(`UPDATE students SET ${key}=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(value,id);audit(user.id,'student_updated','students',id);return {id}},
    profile(token,id){const user=actor(token,'students.read');const row=db.prepare("SELECT s.*,c.name class_name,a.name arm_name FROM students s JOIN class_arms a ON a.id=s.class_arm_id JOIN classes c ON c.id=a.class_id WHERE s.id=?").get(id);if(!row)throw new Error('Student record not found.');if(row.photograph_path&&fs.existsSync(row.photograph_path)){try{const ext=path.extname(row.photograph_path).toLowerCase();const mime=ext==='.png'?'image/png':ext==='.webp'?'image/webp':'image/jpeg';row.photo_data_url='data:'+mime+';base64,'+fs.readFileSync(row.photograph_path).toString('base64')}catch{row.photo_data_url=null}}if(user.roles.includes('Parent')&&!db.prepare('SELECT 1 FROM student_parents sp JOIN parents p ON p.id=sp.parent_id WHERE sp.student_id=? AND p.user_id=?').get(id,user.id))throw new Error('Student record not linked to your parent account.');if(user.roles.includes('Student')&&!db.prepare('SELECT 1 FROM student_portal_link WHERE student_id=? AND user_id=?').get(id,user.id))throw new Error('This is not your student record.');if(user.roles.includes('Teacher')&&!db.prepare('SELECT 1 FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND ta.class_arm_id=?').get(user.id,row.class_arm_id))throw new Error('You may only view profiles for students in your assigned classes.');return{...row,...studentProfileExtras(user,row),parents:db.prepare('SELECT p.id,p.first_name,p.surname,p.phone,p.email,p.address,sp.relationship,sp.primary_contact FROM parents p JOIN student_parents sp ON sp.parent_id=p.id WHERE sp.student_id=?').all(id),attendance:db.prepare('SELECT attendance_date,status,note FROM attendance WHERE student_id=? ORDER BY attendance_date DESC LIMIT 200').all(id),history:db.prepare('SELECT old_status,new_status,effective_on,reason FROM student_status_history WHERE student_id=? ORDER BY effective_on DESC').all(id)}},
    changeStatus(token,id,input){const user=actor(token,'students.manage');if(!['Active','Graduated','Transferred','Withdrawn','Deceased'].includes(input.status))throw new Error('Choose a valid student status.');const row=db.prepare('SELECT status FROM students WHERE id=?').get(id);if(!row)throw new Error('Student record not found.');const reason=text(input.reason,'Reason',300),date=text(input.effectiveOn||now().slice(0,10),'Effective date',10);atomic(()=>{db.prepare('UPDATE students SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(input.status,id);db.prepare('INSERT INTO student_status_history(student_id,old_status,new_status,effective_on,reason,changed_by) VALUES(?,?,?,?,?,?)').run(id,row.status,input.status,date,reason,user.id)});audit(user.id,'student_status_changed','students',id,{from:row.status,to:input.status,reason});return true},
    archive(token,id){const user=actor(token,'students.manage');const result=db.prepare("UPDATE students SET status='Withdrawn',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='Active'").run(id);if(!result.changes)throw new Error('Active student record not found.');audit(user.id,'student_deactivated','students',id);return true},
  }

  function requireRole(role){return db.prepare('SELECT id FROM roles WHERE name=?').get(role)}
  const users={
    list(token){actor(token,'users.manage');return db.prepare('SELECT u.id,u.username,u.email,u.active,u.created_at,GROUP_CONCAT(r.name,\', \') roles FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id GROUP BY u.id ORDER BY u.username').all()},
    create(token,input){const current=actor(token,'users.manage');const username=text(input.username,'Username',60);const role=roles.find(r=>r.toLowerCase()===String(input.role||'').toLowerCase());if(!role)throw new Error('Select one of the school user roles.');if(role==='Parent'&&!input.parentId)throw new Error('Link the parent account to an existing parent record.');if(role==='Student'&&!input.studentId)throw new Error('Link the student account to an existing student record.');if(role==='Stakeholder'&&!input.stakeholderId)throw new Error('Link the stakeholder account to an existing school record.');const secret=password(input.password);const id=uuid();atomic(()=>{db.prepare('INSERT INTO users(id,username,email,password_hash,password_salt) VALUES(?,?,?,?,?)').run(id,username,input.email||null,secret.digest,secret.salt);db.prepare('INSERT INTO user_roles(user_id,role_id) VALUES(?,?)').run(id,requireRole(role).id);if(['Teacher','Finance Officer'].includes(role))db.prepare('INSERT INTO staff(id,user_id,staff_number,first_name,surname,kind) VALUES(?,?,?,?,?,?)').run(uuid(),id,nextSetting('staff-sequence','STF'),text(input.firstName||username,'First name',80),text(input.surname||'Unknown','Surname',80),role==='Teacher'?'Teacher':'Non-teaching');if(role==='Parent'){const result=db.prepare('UPDATE parents SET user_id=? WHERE id=? AND user_id IS NULL').run(id,input.parentId);if(!result.changes)throw new Error('Parent record not found or already linked to an account.');db.prepare('INSERT INTO parent_portal_link(parent_id,user_id) VALUES(?,?)').run(input.parentId,id)}if(role==='Student'){if(!db.prepare('SELECT id FROM students WHERE id=? AND status=\'Active\'').get(input.studentId))throw new Error('Active student record not found.');db.prepare('INSERT INTO student_portal_link(student_id,user_id) VALUES(?,?)').run(input.studentId,id)}if(role==='Stakeholder'){const result=db.prepare("UPDATE stakeholder_schools SET user_id=? WHERE id=? AND user_id IS NULL AND status='Approved'").run(id,input.stakeholderId);if(!result.changes)throw new Error('Approved stakeholder school not found or already linked to an account.')}audit(current.id,'user_created','users',id,{role})});return safeUser(id)},
    update(token,id,input){const current=actor(token,'users.manage');const username=text(input.username,'Username',60);const email=String(input.email||'').trim().toLowerCase()||null;if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Enter a valid email address.');if(db.prepare('SELECT id FROM users WHERE username=? AND id<>?').get(username,id))throw new Error('That username is already in use.');const result=db.prepare('UPDATE users SET username=?,email=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(username,email,id);if(!result.changes)throw new Error('User account not found.');audit(current.id,'user_account_updated','users',id);return safeUser(id)},
    resetPassword(token,id,newPassword){const current=actor(token,'users.manage');if(id===current.id)throw new Error('Ask another administrator to reset your password so you do not lose this session.');const secret=password(newPassword);const result=db.prepare('UPDATE users SET password_hash=?,password_salt=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(secret.digest,secret.salt,id);if(!result.changes)throw new Error('User account not found.');db.prepare('DELETE FROM sessions WHERE user_id=?').run(id);audit(current.id,'user_password_reset','users',id);return true},
    deactivate(token,id){const current=actor(token,'users.manage');if(id===current.id)throw new Error('You cannot deactivate your own account.');const result=db.prepare('UPDATE users SET active=0,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(id);if(!result.changes)throw new Error('User account not found.');db.prepare('DELETE FROM sessions WHERE user_id=?').run(id);audit(current.id,'user_deactivated','users',id);return true},
  }

  function totalsForStudent(studentId,sessionId,termId){const assignments=db.prepare("SELECT fa.id,fa.amount_kobo FROM fee_assignments fa JOIN students s ON s.id=? WHERE fa.session_id=? AND (fa.term_id IS NULL OR fa.term_id=?) AND (fa.student_id=? OR fa.student_id IS NULL AND fa.class_arm_id=s.class_arm_id) ORDER BY fa.id").all(studentId,sessionId,termId,studentId);const eligible= assignments.length?db.prepare("SELECT COALESCE(SUM(amount_kobo),0) amount FROM discounts WHERE student_id=? AND session_id=? AND (term_id IS NULL OR term_id=?) AND approved_at IS NOT NULL").get(studentId,sessionId,termId).amount:0;let assigned=0,discount=0,paid=0,discountRemaining=eligible;const balances=[];for(const item of assignments){const applied=Math.min(item.amount_kobo,discountRemaining);discountRemaining-=applied;const settled=db.prepare("SELECT COALESCE(SUM(pa.amount_kobo),0) n FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.fee_assignment_id=? AND p.status='Verified'").get(item.id).n;assigned+=item.amount_kobo;discount+=applied;paid+=settled;balances.push({id:item.id,amount:item.amount_kobo,discount:applied,paid:settled,outstanding:Math.max(0,item.amount_kobo-applied-settled)})}return{assigned,discount,paid,outstanding:Math.max(0,assigned-discount-paid),assignmentIds:assignments.map(x=>x.id),balances}}
  function financeSummaryRows(term){if(!term)return{expected:0,collected:0,outstanding:0,collections:[]};const list=db.prepare("SELECT id FROM students WHERE status='Active'").all();let expected=0,outstanding=0;for(const s of list){const v=totalsForStudent(s.id,term.session_id,term.id);expected+=Math.max(0,v.assigned-v.discount);outstanding+=v.outstanding}const collected=expected-outstanding;const collections=db.prepare("SELECT date(p.paid_at) day,SUM(p.amount_kobo) amount_kobo FROM payments p WHERE p.status='Verified' AND p.session_id=? AND p.term_id=? GROUP BY date(p.paid_at) ORDER BY day").all(term.session_id,term.id).map(x=>({day:x.day,amount:x.amount_kobo/100}));return{expected:expected/100,collected:collected/100,outstanding:outstanding/100,collections}}
  function studentProfileExtras(user,student){
    const extras={}
    if(user.permissions.includes('finance.read')){
      const term=db.prepare('SELECT t.id,t.session_id,t.name term_name,se.name session_name FROM terms t JOIN academic_sessions se ON se.id=t.session_id WHERE t.active=1 LIMIT 1').get()
      if(term){
        const totals=totalsForStudent(student.id,term.session_id,term.id)
        const assignments=db.prepare("SELECT fa.id,fc.name category,fa.amount_kobo FROM fee_assignments fa JOIN fee_categories fc ON fc.id=fa.category_id WHERE fa.session_id=? AND (fa.term_id IS NULL OR fa.term_id=?) AND (fa.student_id=? OR fa.student_id IS NULL AND fa.class_arm_id=?) ORDER BY fa.id").all(term.session_id,term.id,student.id,student.class_arm_id)
        const payments=db.prepare("SELECT receipt_number,amount_kobo,method,paid_at FROM payments WHERE student_id=? AND session_id=? AND term_id=? AND status='Verified' ORDER BY paid_at DESC").all(student.id,term.session_id,term.id).map(p=>({...p,amount:p.amount_kobo/100}))
        extras.fees={sessionName:term.session_name,termName:term.term_name,assigned:totals.assigned/100,discount:totals.discount/100,paid:totals.paid/100,outstanding:totals.outstanding/100,items:assignments.map(item=>{const balance=totals.balances.find(x=>x.id===item.id);return{category:item.category,amount:item.amount_kobo/100,discount:(balance?.discount||0)/100,paid:(balance?.paid||0)/100,outstanding:(balance?.outstanding||0)/100}}),payments}
      }else extras.fees=null
    }
    if(user.permissions.includes('academics.read')){
      const audienceRestricted=user.roles.some(role=>['Parent','Student'].includes(role))
      const cards=db.prepare(`SELECT rc.id,rc.session_id,rc.term_id,rc.class_teacher_comment,rc.head_teacher_comment,rc.promotion_decision,t.name term_name,se.name session_name FROM report_cards rc JOIN terms t ON t.id=rc.term_id JOIN academic_sessions se ON se.id=rc.session_id WHERE rc.student_id=? ${audienceRestricted?"AND rc.status='Published'":""} ORDER BY se.starts_on DESC,t.id DESC`).all(student.id)
      extras.reportCards=cards.filter(card=>!audienceRestricted||totalsForStudent(student.id,card.session_id,card.term_id).outstanding===0).map(card=>({...card,results:db.prepare("SELECT s.name subject,ROUND(AVG(r.score),1) score FROM results r JOIN subjects s ON s.id=r.subject_id JOIN assessment_components ac ON ac.id=r.component_id WHERE r.student_id=? AND ac.session_id=? AND ac.term_id=? AND r.status='Approved' GROUP BY s.id ORDER BY s.name").all(student.id,card.session_id,card.term_id)}))
    }
    return extras
  }

  const finance={
    categories(token){actor(token,'finance.read');return db.prepare('SELECT * FROM fee_categories ORDER BY name').all()},
    feeAssignments(token){const user=actor(token,'finance.read');if(user.roles.some(role=>['Parent','Student'].includes(role)))throw new Error('Fee schedules are restricted to school finance staff.');return db.prepare('SELECT fa.id,fa.category_id,fa.session_id,fa.term_id,fa.class_arm_id,fa.student_id,fc.name category,se.name session_name,t.name term_name,c.name class_name,a.name arm_name,TRIM(COALESCE(s.first_name||\' \'||s.middle_name||\' \'||s.surname,s.first_name||\' \'||s.surname)) student_name,fa.amount_kobo/100 amount,fa.due_on FROM fee_assignments fa JOIN fee_categories fc ON fc.id=fa.category_id JOIN academic_sessions se ON se.id=fa.session_id LEFT JOIN terms t ON t.id=fa.term_id LEFT JOIN class_arms a ON a.id=fa.class_arm_id LEFT JOIN classes c ON c.id=a.class_id LEFT JOIN students s ON s.id=fa.student_id ORDER BY se.starts_on DESC,fc.name,c.sort_order,a.name,student_name LIMIT 2000').all()},
    createCategory(token,input){const user=actor(token,'finance.manage');const id=Number(db.prepare('INSERT INTO fee_categories(name,description) VALUES(?,?)').run(text(input.name,'Fee category',100),input.description||null).lastInsertRowid);audit(user.id,'fee_category_created','fee_categories',id);return{id}},
    updateCategory(token,id,input){const user=actor(token,'finance.manage');const name=text(input.name,'Fee category',100),description=input.description?text(input.description,'Description',500):null;db.prepare('UPDATE fee_categories SET name=?,description=? WHERE id=?').run(name,description,Number(id));audit(user.id,'fee_category_updated','fee_categories',Number(id));return true},
    deleteCategory(token,id){const user=actor(token,'finance.manage');const categoryId=Number(id);if(db.prepare('SELECT 1 FROM fee_assignments WHERE category_id=? LIMIT 1').get(categoryId))throw new Error('This fee category is assigned to students or classes. Remove or reassign those fees before deleting it.');const result=db.prepare('DELETE FROM fee_categories WHERE id=?').run(categoryId);if(!result.changes)throw new Error('Fee category not found.');audit(user.id,'fee_category_deleted','fee_categories',categoryId);return true},
    summary(token,period){const user=actor(token,'finance.read');const term=period?.termId?db.prepare('SELECT t.id,t.session_id FROM terms t WHERE t.id=?').get(period.termId):db.prepare('SELECT id,session_id FROM terms WHERE active=1 LIMIT 1').get();if(!term)return{expected:0,collected:0,outstanding:0};return financeSummaryRows(term)},
    assignFee(token,input){const user=actor(token,'finance.manage');if(Boolean(input.classArmId)===Boolean(input.studentId))throw new Error('Choose exactly one target: a class arm or an individual student.');const id=uuid();const amount=money(input.amount);db.prepare('INSERT INTO fee_assignments(id,category_id,session_id,term_id,class_arm_id,student_id,amount_kobo,due_on) VALUES(?,?,?,?,?,?,?,?)').run(id,Number(input.categoryId),Number(input.sessionId),input.termId?Number(input.termId):null,input.classArmId?Number(input.classArmId):null,input.studentId||null,amount,input.dueOn||null);audit(user.id,'fee_assigned','fee_assignments',id,{amount_kobo:amount});return{id}},
    updateFeeAssignment(token,id,input){const user=actor(token,'finance.manage');if(Boolean(input.classArmId)===Boolean(input.studentId))throw new Error('Choose exactly one target: a class arm or an individual student.');const amount=money(input.amount),paid=db.prepare('SELECT COALESCE(SUM(amount_kobo),0) amount FROM payment_allocations WHERE fee_assignment_id=?').get(String(id)).amount;if(amount<paid)throw new Error('The fee amount cannot be lower than payments already allocated to it.');const result=db.prepare('UPDATE fee_assignments SET category_id=?,session_id=?,term_id=?,class_arm_id=?,student_id=?,amount_kobo=?,due_on=? WHERE id=?').run(Number(input.categoryId),Number(input.sessionId),input.termId?Number(input.termId):null,input.classArmId?Number(input.classArmId):null,input.studentId||null,amount,input.dueOn||null,String(id));if(!result.changes)throw new Error('Assigned fee not found.');audit(user.id,'fee_assignment_updated','fee_assignments',String(id),{amount_kobo:amount});return true},
    deleteFeeAssignment(token,id){const user=actor(token,'finance.manage');const assignmentId=String(id);if(db.prepare('SELECT 1 FROM payment_allocations WHERE fee_assignment_id=? LIMIT 1').get(assignmentId))throw new Error('This assigned fee has recorded payments and cannot be deleted. Edit it instead.');const result=db.prepare('DELETE FROM fee_assignments WHERE id=?').run(assignmentId);if(!result.changes)throw new Error('Assigned fee not found.');audit(user.id,'fee_assignment_deleted','fee_assignments',assignmentId);return true},
    grantDiscount(token,input){const user=actor(token,'finance.manage');const id=uuid(),amount=money(input.amount);if(!text(input.reason,'Reason',300))throw new Error('A reason is required.');db.prepare('INSERT INTO discounts(id,student_id,session_id,term_id,amount_kobo,reason,approved_by,approved_at) VALUES(?,?,?,?,?,?,?,?)').run(id,input.studentId,Number(input.sessionId),input.termId?Number(input.termId):null,amount,text(input.reason,'Reason',300),user.id,now());audit(user.id,'discount_approved','discounts',id,{amount_kobo:amount});return{id}},
    recordPayment(token,input){const user=actor(token,'finance.manage');return atomic(()=>{const student=db.prepare('SELECT id FROM students WHERE id=?').get(input.studentId);if(!student)throw new Error('Student record not found.');const amount=money(input.amount),sessionId=Number(input.sessionId),termId=Number(input.termId);const balances=totalsForStudent(student.id,sessionId,termId);if(amount>balances.outstanding)throw new Error('Payment exceeds the verified outstanding balance.');const paymentId=uuid(),receipt=nextSetting('receipt-sequence','OSC-RCPT'),idempotencyKey=text(input.idempotencyKey||uuid(),'Payment key',120);if(db.prepare('SELECT id FROM payments WHERE idempotency_key=?').get(idempotencyKey))throw new Error('This payment has already been submitted.');const method=['Cash','Bank Transfer','POS','Cheque','Other'].includes(input.method)?input.method:'Other';const reference=input.reference?text(input.reference,'Payment reference',120):null;if(reference&&db.prepare('SELECT id FROM payments WHERE reference=?').get(reference))throw new Error('This payment reference has already been recorded.');db.prepare("INSERT INTO payments(id,idempotency_key,receipt_number,student_id,session_id,term_id,amount_kobo,method,reference,received_by,status,paid_at,notes) VALUES(?,?,?,?,?,?,?,?,?,?,'Verified',?,?)").run(paymentId,idempotencyKey,receipt,student.id,sessionId,termId,amount,method,reference,user.id,input.paidAt||now(),input.notes||null);let remainder=amount;for(const balance of balances.balances){const alloc=Math.min(remainder,balance.outstanding);if(alloc){db.prepare('INSERT INTO payment_allocations(payment_id,fee_assignment_id,amount_kobo) VALUES(?,?,?)').run(paymentId,balance.id,alloc);remainder-=alloc}if(!remainder)break}audit(user.id,'payment_recorded','payments',paymentId,{receipt_number:receipt,amount_kobo:amount});return{id:paymentId,receiptNumber:receipt,amount:amount/100}})},
    outstanding(token,filter={}){const user=actor(token,'finance.read');if(user.roles.some(r=>['Parent','Student'].includes(r)))throw new Error('Use your linked child or student account view for fee information.');const session=Number(filter.sessionId||db.prepare('SELECT session_id FROM terms WHERE active=1 LIMIT 1').get()?.session_id);if(!session)throw new Error('Set an active academic session first.');const term=Number(filter.termId||db.prepare('SELECT id FROM terms WHERE session_id=? AND active=1').get(session)?.id);const students=filter.classArmId?db.prepare("SELECT * FROM students WHERE status='Active' AND class_arm_id=? ORDER BY surname,first_name").all(Number(filter.classArmId)):db.prepare("SELECT * FROM students WHERE status='Active' ORDER BY surname,first_name").all();return students.map(s=>{const b=totalsForStudent(s.id,session,term);const arm=db.prepare('SELECT c.name class_name,a.name arm_name FROM class_arms a JOIN classes c ON c.id=a.class_id WHERE a.id=?').get(s.class_arm_id);const parent=db.prepare('SELECT p.first_name||\' \'||p.surname name,p.phone FROM parents p JOIN student_parents sp ON sp.parent_id=p.id WHERE sp.student_id=? AND sp.primary_contact=1 LIMIT 1').get(s.id);return{studentId:s.id,name:`${s.first_name} ${s.middle_name} ${s.surname}`.replace(/\s+/g,' ').trim(),admissionNumber:s.admission_number,...arm,parentName:parent?.name||'',parentPhone:parent?.phone||'',assigned:b.assigned/100,discount:b.discount/100,paid:b.paid/100,outstanding:b.outstanding/100}}).filter(x=>x.outstanding>0)},
    myAccount(token){const user=actor(token,'finance.read');if(!user.roles.some(r=>['Parent','Student'].includes(r)))throw new Error('This view is only available to parent and student accounts.');const studentRows=user.roles.includes('Parent')?db.prepare("SELECT s.* FROM students s JOIN student_parents sp ON sp.student_id=s.id JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=? AND s.status='Active'").all(user.id):db.prepare("SELECT s.* FROM students s JOIN student_portal_link l ON l.student_id=s.id WHERE l.user_id=? AND s.status='Active'").all(user.id);return studentRows.map(s=>{const term=db.prepare('SELECT id,session_id FROM terms WHERE active=1 LIMIT 1').get();if(!term)return{studentId:s.id,name:`${s.first_name} ${s.surname}`,outstanding:0,assigned:0,discount:0,paid:0,payments:[]};const b=totalsForStudent(s.id,term.session_id,term.id);const payments=db.prepare("SELECT receipt_number,amount_kobo,method,paid_at,status FROM payments WHERE student_id=? AND session_id=? AND term_id=? AND status='Verified' ORDER BY paid_at DESC").all(s.id,term.session_id,term.id).map(p=>({...p,amount:p.amount_kobo/100}));return{studentId:s.id,name:`${s.first_name} ${s.surname}`,assigned:b.assigned/100,discount:b.discount/100,paid:b.paid/100,outstanding:b.outstanding/100,payments}})},
    payments(token,filter={}){actor(token,'finance.read');if(!actor(token).permissions.includes('finance.manage'))throw new Error('Payment history is restricted to authorised finance staff.');let where='1=1',params=[];if(filter.sessionId){where+=' AND p.session_id=?';params.push(Number(filter.sessionId))}if(filter.termId){where+=' AND p.term_id=?';params.push(Number(filter.termId))}if(filter.status){where+=' AND p.status=?';params.push(filter.status)}if(filter.search){where+=" AND (p.receipt_number LIKE ? OR s.admission_number LIKE ? OR s.first_name||' '||s.surname LIKE ?)";params.push(`%${filter.search}%`,`%${filter.search}%`,`%${filter.search}%`)}return db.prepare(`SELECT p.id,p.receipt_number,p.student_id,p.amount_kobo/100.0 amount,p.method,p.reference,p.status,p.paid_at,p.reversal_reason,s.admission_number,s.first_name||' '||s.surname student_name,u.username received_by FROM payments p JOIN students s ON s.id=p.student_id JOIN users u ON u.id=p.received_by WHERE ${where} ORDER BY p.paid_at DESC LIMIT 1000`).all(...params)},
    reversePayment(token,id,reason){const user=actor(token,'finance.manage');const note=text(reason,'Reversal reason',500);const result=db.prepare("UPDATE payments SET status='Reversed',reversed_by=?,reversal_reason=?,reversed_at=? WHERE id=? AND status='Verified'").run(user.id,note,now(),id);if(!result.changes)throw new Error('Verified payment not found or already reversed.');audit(user.id,'payment_reversed','payments',id,{reason:note});return true},
    receipt(token,receiptNumber){const user=actor(token,'finance.read');const row=db.prepare('SELECT p.*,s.admission_number,s.first_name,s.middle_name,s.surname,a.name arm_name,c.name class_name,sch.name school_name,sch.address school_address,sch.phone school_phone FROM payments p JOIN students s ON s.id=p.student_id JOIN class_arms a ON a.id=s.class_arm_id JOIN classes c ON c.id=a.class_id JOIN schools sch ON sch.id=1 WHERE p.receipt_number=? AND p.status=\'Verified\'').get(text(receiptNumber,'Receipt number',80));if(!row)throw new Error('Verified receipt not found.');if(user.roles.includes('Parent')&&!db.prepare('SELECT 1 FROM student_parents sp JOIN parents p ON p.id=sp.parent_id WHERE sp.student_id=? AND p.user_id=?').get(row.student_id,user.id))throw new Error('You may only access receipts for your linked children.');if(user.roles.includes('Student')&&!db.prepare('SELECT 1 FROM student_portal_link WHERE student_id=? AND user_id=?').get(row.student_id,user.id))throw new Error('You may only access your own receipts.');return{...row,amount:row.amount_kobo/100}},
    expenses(token){actor(token,'finance.read');return db.prepare('SELECT e.*,u.username recorded_by FROM expenses e JOIN users u ON u.id=e.recorded_by ORDER BY e.spent_on DESC,e.id DESC LIMIT 1000').all().map(x=>({...x,amount:x.amount_kobo/100}))},
    expenseCategories(token){actor(token,'finance.read');for(const name of ['Salaries','Utilities','Learning materials','Maintenance','Transport','Other'])db.prepare('INSERT OR IGNORE INTO expense_categories(name) VALUES(?)').run(name);return db.prepare('SELECT * FROM expense_categories WHERE active=1 ORDER BY name').all()},
    addExpenseCategory(token,input){const user=actor(token,'finance.manage');const id=Number(db.prepare('INSERT INTO expense_categories(name) VALUES(?)').run(text(input.name,'Expense category',100)).lastInsertRowid);audit(user.id,'expense_category_created','expense_categories',id);return{id}},
    updateExpenseCategory(token,id,input){const user=actor(token,'finance.manage');db.prepare('UPDATE expense_categories SET name=? WHERE id=?').run(text(input.name,'Expense category',100),Number(id));audit(user.id,'expense_category_updated','expense_categories',Number(id));return true},
    deleteExpenseCategory(token,id){const user=actor(token,'finance.manage'),row=db.prepare('SELECT name FROM expense_categories WHERE id=?').get(Number(id));if(!row)throw new Error('Expense category not found.');if(db.prepare('SELECT 1 FROM expenses WHERE category=? LIMIT 1').get(row.name))throw new Error('This expense category is used by recorded expenses. Edit or remove those expenses before deleting it.');db.prepare('DELETE FROM expense_categories WHERE id=?').run(Number(id));audit(user.id,'expense_category_deleted','expense_categories',Number(id));return true},
    addExpense(token,input){const user=actor(token,'finance.manage');const id=uuid(),amount=money(input.amount),category=text(input.category,'Expense category',100);if(!db.prepare('SELECT 1 FROM expense_categories WHERE name=? AND active=1').get(category))throw new Error('Choose an active expense category.');db.prepare('INSERT INTO expenses(id,category,description,amount_kobo,spent_on,recorded_by) VALUES(?,?,?,?,?,?)').run(id,category,text(input.description,'Description',500),amount,text(input.spentOn||now().slice(0,10),'Date',10),user.id);audit(user.id,'expense_recorded','expenses',id,{amount_kobo:amount});return{id}},
    updateExpense(token,id,input){const user=actor(token,'finance.manage'),category=text(input.category,'Expense category',100),amount=money(input.amount);if(!db.prepare('SELECT 1 FROM expense_categories WHERE name=? AND active=1').get(category))throw new Error('Choose an active expense category.');const result=db.prepare('UPDATE expenses SET category=?,description=?,amount_kobo=?,spent_on=? WHERE id=?').run(category,text(input.description,'Description',500),amount,text(input.spentOn,'Date',10),String(id));if(!result.changes)throw new Error('Expense not found.');audit(user.id,'expense_updated','expenses',String(id),{amount_kobo:amount});return true},
    deleteExpense(token,id){const user=actor(token,'finance.manage'),result=db.prepare('DELETE FROM expenses WHERE id=?').run(String(id));if(!result.changes)throw new Error('Expense not found.');audit(user.id,'expense_deleted','expenses',String(id));return true},
  }

  const academics={
    subjects(token){actor(token,'academics.read');return db.prepare('SELECT * FROM subjects ORDER BY name').all()},
    gradingScales(token){actor(token,'academics.read');return db.prepare('SELECT * FROM grading_scales ORDER BY min_score DESC').all()},
    addGrade(token,input){const user=actor(token,'school.manage');const min=Number(input.minScore),max=Number(input.maxScore);if(!Number.isFinite(min)||!Number.isFinite(max)||min<0||max>100||min>max)throw new Error('Enter a valid grade range between 0 and 100.');if(db.prepare('SELECT 1 FROM grading_scales WHERE NOT(max_score<? OR min_score>?)').get(min,max))throw new Error('Grade ranges cannot overlap.');const id=Number(db.prepare('INSERT INTO grading_scales(name,min_score,max_score,grade,remark) VALUES(?,?,?,?,?)').run(text(input.name,'Scale name',80),min,max,text(input.grade,'Grade',8),text(input.remark,'Remark',80)).lastInsertRowid);audit(user.id,'grading_scale_created','grading_scales',id);return{id}},
    createSubject(token,input){const user=actor(token,'school.manage');const id=Number(db.prepare('INSERT INTO subjects(name,code) VALUES(?,?)').run(text(input.name,'Subject name',120),input.code||null).lastInsertRowid);audit(user.id,'subject_created','subjects',id);return{id}},
    components(token,filter={}){actor(token,'academics.read');let where='1=1',params=[];if(filter.sessionId){where+=' AND ac.session_id=?';params.push(Number(filter.sessionId))}if(filter.termId){where+=' AND ac.term_id=?';params.push(Number(filter.termId))}return db.prepare(`SELECT ac.*,t.name term_name,s.name session_name FROM assessment_components ac JOIN terms t ON t.id=ac.term_id JOIN academic_sessions s ON s.id=ac.session_id WHERE ${where} ORDER BY s.starts_on DESC,t.id,ac.id`).all(...params)},
    createComponent(token,input){const user=actor(token,'school.manage');const max=Number(input.maxScore),weight=Number(input.weight);if(!Number.isFinite(max)||max<=0||!Number.isFinite(weight)||weight<0)throw new Error('Enter a positive maximum score and a non-negative weight.');const id=Number(db.prepare('INSERT INTO assessment_components(session_id,term_id,name,max_score,weight) VALUES(?,?,?,?,?)').run(Number(input.sessionId),Number(input.termId),text(input.name,'Assessment name',100),max,weight).lastInsertRowid);audit(user.id,'assessment_component_created','assessment_components',id);return{id}},
    recordResult(token,input){const user=actor(token,'academics.manage');if(user.roles.includes('Teacher')&&!user.roles.includes('Super Admin')){const allowed=db.prepare('SELECT 1 FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id JOIN students s ON s.class_arm_id=ta.class_arm_id WHERE st.user_id=? AND s.id=? AND ta.subject_id=?').get(user.id,input.studentId,Number(input.subjectId));if(!allowed)throw new Error('You are not assigned to this student and subject.')}const score=Number(input.score);if(!Number.isFinite(score)||score<0)throw new Error('Enter a valid score.');const comp=db.prepare('SELECT max_score FROM assessment_components WHERE id=?').get(Number(input.componentId));if(!comp||score>comp.max_score)throw new Error('Score must be within the assessment maximum.');const existing=db.prepare('SELECT id,status FROM results WHERE student_id=? AND subject_id=? AND component_id=?').get(input.studentId,Number(input.subjectId),Number(input.componentId));if(existing&&existing.status!=='Draft')throw new Error('Submitted or approved results cannot be edited. Ask an authorised administrator to reopen the result.');const id=existing?.id||uuid();db.prepare("INSERT INTO results(id,student_id,subject_id,component_id,score,entered_by,status) VALUES(?,?,?,?,?,?,'Draft') ON CONFLICT(student_id,subject_id,component_id) DO UPDATE SET score=excluded.score,entered_by=excluded.entered_by,updated_at=CURRENT_TIMESTAMP").run(id,input.studentId,Number(input.subjectId),Number(input.componentId),score,user.id);audit(user.id,'result_recorded','results',id);return{id}},
    results(token,filter={}){const user=actor(token,'academics.read');let where='1=1',params=[];if(filter.sessionId){where+=' AND c.session_id=?';params.push(Number(filter.sessionId))}if(filter.termId){where+=' AND c.term_id=?';params.push(Number(filter.termId))}if(user.roles.includes('Teacher')){where+=' AND EXISTS(SELECT 1 FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND ta.class_arm_id=s.class_arm_id AND ta.subject_id=r.subject_id)';params.push(user.id)}if(user.roles.includes('Parent')){where+=' AND r.status=\'Approved\' AND s.id IN (SELECT sp.student_id FROM student_parents sp JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=?)';params.push(user.id)}if(user.roles.includes('Student')){where+=' AND r.status=\'Approved\' AND s.id=(SELECT student_id FROM student_portal_link WHERE user_id=?)';params.push(user.id)}return db.prepare(`SELECT r.id,r.student_id,s.admission_number,s.first_name||' '||s.surname student_name,sub.name subject,c.name component,c.session_id,c.term_id,r.score,c.max_score,r.status,r.updated_at FROM results r JOIN students s ON s.id=r.student_id JOIN subjects sub ON sub.id=r.subject_id JOIN assessment_components c ON c.id=r.component_id WHERE ${where} ORDER BY s.surname,s.first_name,sub.name,c.id`).all(...params)},
    submitResults(token,input){const user=actor(token,'academics.manage');let scope='status=\'Draft\'',params=[];if(input.sessionId){scope+=' AND component_id IN (SELECT id FROM assessment_components WHERE session_id=?)';params.push(Number(input.sessionId))}if(input.termId){scope+=' AND component_id IN (SELECT id FROM assessment_components WHERE term_id=?)';params.push(Number(input.termId))}if(user.roles.includes('Teacher')){scope+=' AND id IN (SELECT r.id FROM results r JOIN students s ON s.id=r.student_id JOIN teacher_assignments ta ON ta.class_arm_id=s.class_arm_id JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND ta.subject_id=r.subject_id)';params.push(user.id)}const count=db.prepare(`UPDATE results SET status='Submitted',updated_at=CURRENT_TIMESTAMP WHERE ${scope}`).run(...params).changes;audit(user.id,'results_submitted','results',null,{count});return{submitted:count}},
    approveResults(token,input){const user=actor(token,'school.manage');const sessionId=Number(input.sessionId),termId=Number(input.termId);const term=db.prepare('SELECT name FROM terms WHERE id=? AND session_id=?').get(termId,sessionId);if(!term)throw new Error('Select a valid academic session and term.');const count=db.prepare("UPDATE results SET status='Approved',updated_at=CURRENT_TIMESTAMP WHERE status='Submitted' AND component_id IN (SELECT id FROM assessment_components WHERE session_id=? AND term_id=?)").run(sessionId,termId).changes;const students=db.prepare("SELECT DISTINCT s.id FROM students s JOIN results r ON r.student_id=s.id JOIN assessment_components c ON c.id=r.component_id WHERE s.status='Active' AND c.session_id=? AND c.term_id=? AND r.status='Approved'").all(sessionId,termId);const created=db.transaction(()=>students.forEach(s=>db.prepare('INSERT OR IGNORE INTO report_cards(id,student_id,session_id,term_id,status) VALUES(?,?,?,? ,\'Draft\')').run(uuid(),s.id,sessionId,termId)));created();audit(user.id,'results_approved','results',null,{count,sessionId,termId,reportCards:students.length});return{approved:count,reportCards:students.length}},
    setPromotion(token,input){const user=actor(token,'school.manage');const sessionId=Number(input.sessionId),termId=Number(input.termId);if(db.prepare('SELECT name FROM terms WHERE id=? AND session_id=?').get(termId,sessionId)?.name!=='Third Term')throw new Error('Promotion and repetition decisions may only be recorded for Third Term.');if(!['Promoted','Repeated','Graduated','Transferred'].includes(input.decision))throw new Error('Choose an authorised promotion decision.');const decision=input.decision;db.prepare('INSERT INTO promotion_records(student_id,session_id,decision,decided_by) VALUES(?,?,?,?) ON CONFLICT(student_id,session_id) DO UPDATE SET decision=excluded.decision,decided_by=excluded.decided_by,decided_at=CURRENT_TIMESTAMP').run(input.studentId,sessionId,decision,user.id);db.prepare("UPDATE report_cards SET promotion_decision=? WHERE student_id=? AND session_id=? AND term_id=?").run(decision,input.studentId,sessionId,termId);audit(user.id,'promotion_decision_recorded','promotion_records',input.studentId,{sessionId,decision});return{studentId:input.studentId,decision}},
    reportCards(token,filter={}){const user=actor(token,'academics.read');let where='1=1',params=[];if(filter.sessionId){where+=' AND rc.session_id=?';params.push(Number(filter.sessionId))}if(filter.termId){where+=' AND rc.term_id=?';params.push(Number(filter.termId))}if(user.roles.includes('Parent')){where+=" AND rc.status='Published' AND s.id IN (SELECT sp.student_id FROM student_parents sp JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=?)";params.push(user.id)}if(user.roles.includes('Student')){where+=" AND rc.status='Published' AND s.id=(SELECT student_id FROM student_portal_link WHERE user_id=?)";params.push(user.id)}if(user.roles.includes('Teacher')){where+=' AND EXISTS(SELECT 1 FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND ta.class_arm_id=s.class_arm_id)';params.push(user.id)}const list=db.prepare(`SELECT rc.*,s.admission_number,s.first_name||' '||s.surname student_name,c.name class_name,a.name arm_name,t.name term_name,se.name session_name FROM report_cards rc JOIN students s ON s.id=rc.student_id JOIN class_arms a ON a.id=s.class_arm_id JOIN classes c ON c.id=a.class_id JOIN terms t ON t.id=rc.term_id JOIN academic_sessions se ON se.id=rc.session_id WHERE ${where} ORDER BY se.starts_on DESC,t.id,s.surname,s.first_name`).all(...params);return list.map(row=>{const balance=totalsForStudent(row.student_id,row.session_id,row.term_id);const accessRequired=user.roles.some(r=>['Parent','Student'].includes(r));if(accessRequired)return{...row,financially_cleared:balance.outstanding===0};if(user.permissions.includes('finance.read'))return{...row,financially_cleared:balance.outstanding===0,outstanding:balance.outstanding/100};return row}).filter(row=>!user.roles.some(r=>['Parent','Student'].includes(r))||row.financially_cleared)},
    saveReportComments(token,input){const user=actor(token,'academics.manage');const report=db.prepare('SELECT rc.id,rc.status,s.class_arm_id FROM report_cards rc JOIN students s ON s.id=rc.student_id WHERE rc.id=?').get(input.id);if(!report)throw new Error('Report card not found.');const isAdmin=user.permissions.includes('school.manage');if(!isAdmin&&report.status!=='Draft')throw new Error('Teachers can edit comments before the report card is published.');if(!isAdmin&&!db.prepare('SELECT 1 FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND ta.class_arm_id=?').get(user.id,report.class_arm_id))throw new Error('You are not assigned to this class.');const teacher=String(input.classTeacherComment||'').trim().slice(0,1000);if(isAdmin){const head=String(input.headTeacherComment||'').trim().slice(0,1000);db.prepare('UPDATE report_cards SET class_teacher_comment=?,head_teacher_comment=? WHERE id=?').run(teacher||null,head||null,report.id)}else db.prepare('UPDATE report_cards SET class_teacher_comment=? WHERE id=?').run(teacher||null,report.id);audit(user.id,'report_card_comments_saved','report_cards',report.id);return true},
    publishReport(token,id){const user=actor(token,'academics.manage');if(!user.permissions.includes('school.manage'))throw new Error('Only an authorised administrator may publish report cards.');db.prepare("UPDATE report_cards SET status='Published',published_by=?,published_at=? WHERE id=?").run(user.id,now(),id);audit(user.id,'report_card_published','report_cards',id);return true},
    getReportCard(token,studentId,sessionId,termId){const user=actor(token,'academics.read');const restricted=user.roles.some(role=>['Parent','Student'].includes(role));const report=db.prepare(`SELECT rc.*,s.class_arm_id FROM report_cards rc JOIN students s ON s.id=rc.student_id WHERE rc.student_id=? AND rc.session_id=? AND rc.term_id=? ${restricted?"AND rc.status='Published'":""}`).get(studentId,Number(sessionId),Number(termId));if(!report)throw new Error('This report card is not available.');if(user.roles.includes('Parent')){const linked=db.prepare('SELECT 1 FROM student_parents sp JOIN parents p ON p.id=sp.parent_id WHERE sp.student_id=? AND p.user_id=?').get(studentId,user.id);if(!linked)throw new Error('You do not have access to this student record.')}if(user.roles.includes('Student')){const linked=db.prepare('SELECT 1 FROM student_portal_link WHERE student_id=? AND user_id=?').get(studentId,user.id);if(!linked)throw new Error('You do not have access to this student record.')}if(user.roles.includes('Teacher')&&!db.prepare('SELECT 1 FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND ta.class_arm_id=?').get(user.id,report.class_arm_id))throw new Error('You may only view report cards for your assigned classes.');if(restricted){const balance=totalsForStudent(studentId,Number(sessionId),Number(termId));if(balance.outstanding>0)throw new Error(`Report card access is restricted until the outstanding fees of ₦${(balance.outstanding/100).toLocaleString('en-NG',{minimumFractionDigits:2})} are settled.`)}return{...report,results:db.prepare("SELECT s.name subject,AVG(r.score) total_score FROM results r JOIN subjects s ON s.id=r.subject_id JOIN assessment_components c ON c.id=r.component_id WHERE r.student_id=? AND c.session_id=? AND c.term_id=? AND r.status='Approved' GROUP BY s.id ORDER BY s.name").all(studentId,Number(sessionId),Number(termId))}},
  }
  const attendance={
    classes(token){const user=actor(token,'attendance.read');if(user.roles.includes('Teacher'))return db.prepare("SELECT c.id,c.name,a.id class_arm_id,a.name arm_name FROM teacher_assignments ta JOIN staff s ON s.id=ta.staff_id JOIN class_arms a ON a.id=ta.class_arm_id JOIN classes c ON c.id=a.class_id WHERE s.user_id=? ORDER BY c.sort_order,a.name").all(user.id);return db.prepare('SELECT c.id,c.name,a.id class_arm_id,a.name arm_name FROM classes c JOIN class_arms a ON a.class_id=c.id ORDER BY c.sort_order,a.name').all()},
    list(token,filter={}){const user=actor(token,'attendance.read');let where=['1=1'],params=[];if(filter.date){where.push('a.attendance_date=?');params.push(filter.date)}if(filter.classArmId){where.push('a.class_arm_id=?');params.push(Number(filter.classArmId))}if(user.roles.includes('Teacher')){where.push('a.class_arm_id IN (SELECT class_arm_id FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=?)');params.push(user.id)}if(user.roles.includes('Parent')){where.push('s.id IN (SELECT student_id FROM student_parents sp JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=?)');params.push(user.id)}if(user.roles.includes('Student')){where.push('s.id=(SELECT student_id FROM student_portal_link WHERE user_id=?)');params.push(user.id)}return db.prepare(`SELECT a.*,s.admission_number,s.first_name||' '||s.surname student_name FROM attendance a JOIN students s ON s.id=a.student_id WHERE ${where.join(' AND ')} ORDER BY a.attendance_date DESC,s.surname`).all(...params)},
    mark(token,records){const user=actor(token,'attendance.manage');if(!Array.isArray(records)||records.length>500)throw new Error('Provide up to 500 attendance records.');return atomic(()=>{for(const item of records){const student=db.prepare("SELECT class_arm_id FROM students WHERE id=? AND status='Active'").get(item.studentId);if(!student||student.class_arm_id!==Number(item.classArmId))throw new Error('Student is not an active member of the selected class arm.');if(user.roles.includes('Teacher')&&!db.prepare('SELECT 1 FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND ta.class_arm_id=?').get(user.id,Number(item.classArmId)))throw new Error('You are not assigned to this class.');if(!['Present','Absent','Late','Excused'].includes(item.status))throw new Error('Select a valid attendance status.');db.prepare('INSERT INTO attendance(student_id,class_arm_id,marked_by,attendance_date,status,note) VALUES(?,?,?,?,?,?) ON CONFLICT(student_id,attendance_date) DO UPDATE SET status=excluded.status,note=excluded.note,marked_by=excluded.marked_by').run(item.studentId,Number(item.classArmId),user.id,text(item.date,'Date',10),item.status,item.note||null)}audit(user.id,'attendance_marked','attendance',null,{count:records.length});return{saved:records.length}})},
  }
  const stakeholders={
    selfRegister(input){return atomic(()=>{const username=text(input.username,'Username',60),secret=password(input.password),userId=uuid(),schoolId=uuid();if(!/^\S+@\S+\.\S+$/.test(String(input.email||'')))throw new Error('Enter a valid school email address.');db.prepare('INSERT INTO users(id,username,email,password_hash,password_salt) VALUES(?,?,?,?,?)').run(userId,username,text(input.email,'Email',254),secret.digest,secret.salt);db.prepare("INSERT INTO user_roles(user_id,role_id) VALUES(?,(SELECT id FROM roles WHERE name='Stakeholder'))").run(userId);db.prepare("INSERT INTO stakeholder_schools(id,name,address,phone,email,representative,user_id,status) VALUES(?,?,?,?,?,?,?,'Pending')").run(schoolId,text(input.name,'School name'),input.address||null,text(input.phone,'Contact number',40),text(input.email,'Email',254),text(input.representative,'Authorised representative'),userId);audit(userId,'stakeholder_application_submitted','stakeholder_schools',schoolId);return{token:auth.createSession(userId),user:safeUser(userId),status:'Pending'}})},
    list(token){const user=actor(token,'stakeholders.read');const columns="ss.id,ss.name,ss.address,ss.phone,ss.email,ss.representative,ss.status,ss.created_at,(SELECT COUNT(*) FROM stakeholder_registrations r WHERE r.stakeholder_id=ss.id) student_count,(SELECT COUNT(*) FROM stakeholder_registrations r WHERE r.stakeholder_id=ss.id AND r.exam_type LIKE '%WAEC%') waec_count,(SELECT COUNT(*) FROM stakeholder_registrations r WHERE r.stakeholder_id=ss.id AND r.exam_type LIKE '%NECO%') neco_count,(SELECT COUNT(*) FROM stakeholder_registrations r WHERE r.stakeholder_id=ss.id AND r.exam_type LIKE '%JAMB%') jamb_count,(SELECT COUNT(*) FROM stakeholder_registrations r WHERE r.stakeholder_id=ss.id AND r.exam_type='BECE') bece_count,(SELECT COUNT(*) FROM stakeholder_registrations r WHERE r.stakeholder_id=ss.id AND r.exam_type='Common Entrance') common_entrance_count";if(user.roles.includes('Stakeholder'))return db.prepare(`SELECT ${columns} FROM stakeholder_schools ss WHERE ss.user_id=?`).all(user.id);return db.prepare(`SELECT ${columns} FROM stakeholder_schools ss ORDER BY ss.created_at DESC`).all()},
    register(token,input){const user=actor(token,'stakeholders.manage');const id=uuid();db.prepare('INSERT INTO stakeholder_schools(id,name,address,phone,email,representative) VALUES(?,?,?,?,?,?)').run(id,text(input.name,'School name'),input.address||null,text(input.phone,'Phone',40),input.email||null,text(input.representative,'Representative'));audit(user.id,'stakeholder_registered','stakeholder_schools',id);return{id}},
    update(token,id,input){const user=actor(token,'stakeholders.manage');const result=db.prepare('UPDATE stakeholder_schools SET name=?,address=?,phone=?,email=?,representative=? WHERE id=?').run(text(input.name,'School name'),input.address||null,text(input.phone,'Phone',40),input.email||null,text(input.representative,'Representative'),id);if(!result.changes)throw new Error('Stakeholder school not found.');audit(user.id,'stakeholder_updated','stakeholder_schools',id);return{id}},
    deactivate(token,id){const user=actor(token,'stakeholders.manage');const record=db.prepare('SELECT user_id FROM stakeholder_schools WHERE id=?').get(id);if(!record)throw new Error('Stakeholder school not found.');atomic(()=>{db.prepare("UPDATE stakeholder_schools SET status='Inactive' WHERE id=?").run(id);if(record.user_id){db.prepare('UPDATE users SET active=0,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(record.user_id);db.prepare('DELETE FROM sessions WHERE user_id=?').run(record.user_id)}});audit(user.id,'stakeholder_deactivated','stakeholder_schools',id);return true},
    review(token,id,decision){const user=actor(token,'stakeholders.manage');if(!['Approved','Rejected','Inactive'].includes(decision))throw new Error('Select a valid review decision.');const record=db.prepare('SELECT user_id FROM stakeholder_schools WHERE id=?').get(id);if(!record)throw new Error('Stakeholder school not found.');atomic(()=>{db.prepare('UPDATE stakeholder_schools SET status=? WHERE id=?').run(decision,id);if(record.user_id){db.prepare('UPDATE users SET active=? WHERE id=?').run(decision==='Approved'?1:0,record.user_id);if(decision!=='Approved')db.prepare('DELETE FROM sessions WHERE user_id=?').run(record.user_id);db.prepare('INSERT INTO notifications(id,user_id,title,body) VALUES(?,?,?,?)').run(uuid(),record.user_id,'Stakeholder account reviewed',`Your school account was ${decision.toLowerCase()}.`)}});audit(user.id,'stakeholder_reviewed','stakeholder_schools',id,{decision});return true},
    registrations(token){actor(token,'stakeholders.manage');return db.prepare("SELECT r.*,r.amount_paid_kobo/100.0 amount_paid,r.amount_due_kobo/100.0 amount_due,MAX(r.amount_due_kobo-r.amount_paid_kobo,0)/100.0 outstanding_balance,CASE WHEN r.amount_due_kobo<=0 THEN 'Not priced' WHEN r.amount_paid_kobo<=0 THEN 'Unpaid' WHEN r.amount_paid_kobo>=r.amount_due_kobo THEN 'Paid' ELSE 'Part-paid' END payment_status,s.name stakeholder_name,se.name session_name,c.name class_name,a.name arm_name FROM stakeholder_registrations r JOIN stakeholder_schools s ON s.id=r.stakeholder_id JOIN academic_sessions se ON se.id=r.requested_session_id LEFT JOIN class_arms a ON a.id=r.assigned_class_arm_id LEFT JOIN classes c ON c.id=a.class_id ORDER BY r.created_at DESC").all().map(r=>({...r,documents:JSON.parse(r.documents_json)}))},
    recordStudent(token,input){const user=actor(token,'stakeholders.manage');const stakeholder=db.prepare('SELECT id FROM stakeholder_schools WHERE id=?').get(input.stakeholderId);if(!stakeholder)throw new Error('Select a valid stakeholder school.');const session=Number(input.sessionId);if(!db.prepare('SELECT id FROM academic_sessions WHERE id=?').get(session))throw new Error('Select a valid academic session.');const exams=['WAEC','NECO','JAMB','BECE','CASS','Common Entrance','WAEC & NECO','WAEC, NECO & JAMB'];if(!exams.includes(input.examType))throw new Error('Choose a valid examination.');const amount=Number(input.amountPaid||0);if(!Number.isFinite(amount)||amount<0||amount>1000000000)throw new Error('Enter a valid non-negative amount paid.');const id=uuid();db.prepare('INSERT INTO stakeholder_registrations(id,stakeholder_id,first_name,surname,date_of_birth,gender,exam_type,requested_session_id,amount_paid_kobo) VALUES(?,?,?,?,?,?,?,?,?)').run(id,stakeholder.id,text(input.firstName,'First name'),text(input.surname,'Surname'),input.dateOfBirth||null,input.gender||null,input.examType,session,Math.round(amount*100));audit(user.id,'stakeholder_student_recorded','stakeholder_registrations',id,{stakeholderId:stakeholder.id,examType:input.examType,amountPaid:amount});return{id,status:'Pending'}},
    updatePayment(token,id,input){const user=actor(token,'stakeholders.manage');const paid=Number(input.amountPaid),due=Number(input.amountDue);if(!Number.isFinite(paid)||paid<0||paid>100000000000||!Number.isFinite(due)||due<0||due>100000000000)throw new Error('Enter valid non-negative payment amounts.');const result=db.prepare('UPDATE stakeholder_registrations SET amount_paid_kobo=?,amount_due_kobo=? WHERE id=?').run(Math.round(paid*100),Math.round(due*100),id);if(!result.changes)throw new Error('Student application not found.');audit(user.id,'stakeholder_registration_payment_updated','stakeholder_registrations',id,{amountPaid:paid,amountDue:due});return true},
    reviewStudent(token,id,input){const user=actor(token,'stakeholders.manage');const application=db.prepare('SELECT * FROM stakeholder_registrations WHERE id=?').get(id);if(!application)throw new Error('Student application not found.');if(application.status!=='Pending')throw new Error('Only pending applications can be reviewed.');if(!['Approved','Rejected'].includes(input.decision))throw new Error('Choose Approved or Rejected.');if(input.decision==='Rejected'){db.prepare("UPDATE stakeholder_registrations SET status='Rejected',decision_note=? WHERE id=?").run(input.note||null,id)}else{if(!application.gender)throw new Error('The application must include the student gender before admission approval.');const arm=db.prepare('SELECT id FROM class_arms WHERE id=?').get(Number(input.classArmId));if(!arm)throw new Error('Select a valid class arm.');const admitted=atomic(()=>{const admission=nextSetting('admission-sequence','OSC'),studentId=uuid();db.prepare("INSERT INTO students(id,admission_number,first_name,middle_name,surname,gender,date_of_birth,nationality,admission_date,session_id,class_arm_id) VALUES(?,?,?,'',?,?,?,?,?,?,?)").run(studentId,admission,application.first_name,application.surname,application.gender,application.date_of_birth,'Nigerian',now().slice(0,10),application.requested_session_id,arm.id);db.prepare("UPDATE stakeholder_registrations SET status='Approved',decision_note=?,assigned_admission_number=?,assigned_class_arm_id=? WHERE id=? AND status='Pending'").run(input.note||null,admission,arm.id,id);return{studentId,admission}});db.prepare('INSERT INTO notifications(id,user_id,title,body) SELECT ?,user_id,?,? FROM stakeholder_schools WHERE id=? AND user_id IS NOT NULL').run(uuid(),'Student application approved',`Admission number ${admitted.admission} has been assigned.`,application.stakeholder_id);audit(user.id,'stakeholder_student_admitted','students',admitted.studentId,{admission_number:admitted.admission,applicationId:id});return admitted}db.prepare('INSERT INTO notifications(id,user_id,title,body) SELECT ?,user_id,?,? FROM stakeholder_schools WHERE id=? AND user_id IS NOT NULL').run(uuid(),'Student application reviewed','The host school has reviewed your student application.',application.stakeholder_id);audit(user.id,'stakeholder_student_rejected','stakeholder_registrations',id,{note:input.note||''});return{status:input.decision}},
    reviewStudent(token,id,input){const user=actor(token,'stakeholders.manage');const application=db.prepare('SELECT * FROM stakeholder_registrations WHERE id=?').get(id);if(!application)throw new Error('Student application not found.');if(application.status!=='Pending')throw new Error('Only pending applications can be reviewed.');if(!['Approved','Rejected'].includes(input.decision))throw new Error('Choose Approved or Rejected.');if(input.decision==='Rejected'){db.prepare("UPDATE stakeholder_registrations SET status='Rejected',decision_note=? WHERE id=?").run(input.note||null,id)}else{if(!application.gender)throw new Error('The application must include the student gender before admission approval.');const arm=db.prepare('SELECT id FROM class_arms WHERE id=?').get(Number(input.classArmId));if(!arm)throw new Error('Select a valid class arm.');const admitted=atomic(()=>{const admission=nextSetting('admission-sequence','OSC'),studentId=uuid();db.prepare("INSERT INTO students(id,admission_number,first_name,middle_name,surname,gender,date_of_birth,nationality,admission_date,session_id,class_arm_id) VALUES(?,?,?,'',?,?,?,?,?,?,?)").run(studentId,admission,application.first_name,application.surname,application.gender,application.date_of_birth,'Nigerian',now().slice(0,10),application.requested_session_id,arm.id);db.prepare("UPDATE stakeholder_registrations SET status='Approved',decision_note=?,assigned_admission_number=?,assigned_class_arm_id=? WHERE id=? AND status='Pending'").run(input.note||null,admission,arm.id,id);return{studentId,admission}});db.prepare('INSERT INTO notifications(id,user_id,title,body) SELECT ?,user_id,?,? FROM stakeholder_schools WHERE id=? AND user_id IS NOT NULL').run(uuid(),'Student application approved',`Admission number ${admitted.admission} has been assigned.`,application.stakeholder_id);audit(user.id,'stakeholder_student_admitted','students',admitted.studentId,{admission_number:admitted.admission,applicationId:id});return admitted}db.prepare('INSERT INTO notifications(id,user_id,title,body) SELECT ?,user_id,?,? FROM stakeholder_schools WHERE id=? AND user_id IS NOT NULL').run(uuid(),'Student application reviewed','The host school has reviewed your student application.',application.stakeholder_id);audit(user.id,'stakeholder_student_rejected','stakeholder_registrations',id,{note:input.note||''});return{status:input.decision}},
    registerStudent(token,input){const user=actor(token);if(!user.roles.includes('Stakeholder'))throw new Error('Stakeholder portal access is required.');const stakeholder=db.prepare('SELECT id,status FROM stakeholder_schools WHERE user_id=?').get(user.id);if(!stakeholder||stakeholder.status!=='Approved')throw new Error('Your stakeholder school registration must be approved first.');const exams=['WAEC','NECO','JAMB','BECE','CASS','Common Entrance','WAEC & NECO','WAEC, NECO & JAMB'];if(!exams.includes(input.examType))throw new Error('Choose WAEC, NECO, JAMB, BECE, CASS, Common Entrance, or an available combination.');const id=uuid();db.prepare("INSERT INTO stakeholder_registrations(id,stakeholder_id,first_name,surname,date_of_birth,gender,exam_type,photograph_path,documents_json,requested_session_id) VALUES(?,?,?,?,?,?,?,?,?,?)").run(id,stakeholder.id,text(input.firstName,'First name'),text(input.surname,'Surname'),input.dateOfBirth||null,input.gender||null,input.examType,input.photographPath||null,JSON.stringify(input.documents||[]),Number(input.sessionId));audit(user.id,'stakeholder_student_submitted','stakeholder_registrations',id,{examType:input.examType});return{id}},
    myRegistrations(token){const user=actor(token);if(!user.roles.includes('Stakeholder'))throw new Error('Stakeholder portal access is required.');return db.prepare("SELECT r.id,r.first_name,r.surname,r.exam_type,r.status,r.decision_note,r.assigned_admission_number,r.amount_paid_kobo/100.0 amount_paid,r.amount_due_kobo/100.0 amount_due,MAX(r.amount_due_kobo-r.amount_paid_kobo,0)/100.0 outstanding_balance,CASE WHEN r.amount_due_kobo<=0 THEN 'Not priced' WHEN r.amount_paid_kobo<=0 THEN 'Unpaid' WHEN r.amount_paid_kobo>=r.amount_due_kobo THEN 'Paid' ELSE 'Part-paid' END payment_status,c.name class_name,a.name arm_name,r.created_at FROM stakeholder_registrations r JOIN stakeholder_schools s ON s.id=r.stakeholder_id LEFT JOIN class_arms a ON a.id=r.assigned_class_arm_id LEFT JOIN classes c ON c.id=a.class_id WHERE s.user_id=? ORDER BY r.created_at DESC").all(user.id)},
  }
  const communication={
    announcements(token){const user=actor(token,'communication.read');return db.prepare("SELECT a.*,u.username author FROM announcements a JOIN users u ON u.id=a.published_by WHERE a.expires_at IS NULL OR a.expires_at>=date('now') ORDER BY a.published_at DESC").all().filter(a=>a.audience==='All'||user.roles.some(r=>a.audience.split(',').includes(r)))},
    recipients(token){const user=actor(token,'communication.manage');if(user.roles.includes('Teacher'))return db.prepare("SELECT DISTINCT u.id,u.username FROM users u JOIN parents p ON p.user_id=u.id JOIN student_parents sp ON sp.parent_id=p.id JOIN students s ON s.id=sp.student_id JOIN teacher_assignments ta ON ta.class_arm_id=s.class_arm_id JOIN staff st ON st.id=ta.staff_id WHERE st.user_id=? AND u.active=1 ORDER BY u.username").all(user.id);if(user.roles.includes('Parent'))return db.prepare("SELECT DISTINCT u.id,u.username FROM users u JOIN staff st ON st.user_id=u.id JOIN teacher_assignments ta ON ta.staff_id=st.id JOIN students s ON s.class_arm_id=ta.class_arm_id JOIN student_parents sp ON sp.student_id=s.id JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=? AND u.active=1 ORDER BY u.username").all(user.id);if(user.permissions.includes('school.manage'))return db.prepare("SELECT u.id,u.username FROM users u WHERE u.active=1 AND u.id<>? ORDER BY u.username").all(user.id);return[]},
    createAnnouncement(token,input){const user=actor(token,'communication.manage');if(!user.permissions.includes('school.manage'))throw new Error('Only an authorised school administrator may publish school-wide announcements.');const id=uuid(),audience=input.audience||'All',allowedAudiences=['All','Teacher','Parent','Student','Stakeholder','Finance Officer'];if(!allowedAudiences.includes(audience))throw new Error('Choose a valid announcement audience.');const title=text(input.title,'Title',180),body=text(input.body,'Message',10000);atomic(()=>{db.prepare('INSERT INTO announcements(id,title,body,audience,published_by,expires_at) VALUES(?,?,?,?,?,?)').run(id,title,body,audience,user.id,input.expiresAt||null);const audienceNames=audience==='All'?null:audience.split(',').map(s=>s.trim());const recipients=db.prepare(`SELECT DISTINCT u.id FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.active=1 ${audienceNames?'AND r.name IN ('+audienceNames.map(()=>'?').join(',')+')':''}`).all(...(audienceNames||[]));for(const recipient of recipients)db.prepare('INSERT INTO notifications(id,user_id,title,body) VALUES(?,?,?,?)').run(uuid(),recipient.id,title,body);audit(user.id,'announcement_published','announcements',id,{recipientCount:recipients.length})});return{id}},
    messages(token){const user=actor(token,'communication.read');return db.prepare('SELECT m.*,sender.username sender,recipient.username recipient,(m.recipient_id=?) is_recipient FROM messages m JOIN users sender ON sender.id=m.sender_id JOIN users recipient ON recipient.id=m.recipient_id WHERE m.sender_id=? OR m.recipient_id=? ORDER BY m.sent_at DESC').all(user.id,user.id,user.id)},
    markMessageRead(token,id){const user=actor(token,'communication.read');const result=db.prepare('UPDATE messages SET read_at=COALESCE(read_at,?) WHERE id=? AND recipient_id=?').run(now(),id,user.id);if(!result.changes)throw new Error('Message not found in your inbox.');return true},
    sendMessage(token,input){const user=actor(token,'communication.manage');const id=uuid();const recipient=db.prepare('SELECT id FROM users WHERE id=? AND active=1').get(input.recipientId);if(!recipient)throw new Error('Recipient account not found.');if(user.roles.includes('Teacher')){const related=db.prepare("SELECT 1 FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id JOIN students s ON s.class_arm_id=ta.class_arm_id JOIN student_parents sp ON sp.student_id=s.id JOIN parents p ON p.id=sp.parent_id WHERE st.user_id=? AND p.user_id=? LIMIT 1").get(user.id,input.recipientId);if(!related)throw new Error('Teachers may message only guardians in their assigned classes.')}if(user.roles.includes('Parent')){const related=db.prepare("SELECT 1 FROM student_parents sp JOIN parents p ON p.id=sp.parent_id JOIN students s ON s.id=sp.student_id JOIN teacher_assignments ta ON ta.class_arm_id=s.class_arm_id JOIN staff st ON st.id=ta.staff_id WHERE p.user_id=? AND st.user_id=? LIMIT 1").get(user.id,input.recipientId);if(!related)throw new Error('Parents may message only authorised teachers for their children.')}const subject=input.subject?text(input.subject,'Subject',180):'New school message',body=text(input.body,'Message',10000);db.prepare('INSERT INTO messages(id,sender_id,recipient_id,subject,body) VALUES(?,?,?,?,?)').run(id,user.id,input.recipientId,subject,body);db.prepare('INSERT INTO notifications(id,user_id,title,body) VALUES(?,?,?,?)').run(uuid(),input.recipientId,subject,body.slice(0,500));audit(user.id,'message_sent','messages',id);return{id}},
    notifications(token){const user=actor(token);return db.prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 200').all(user.id)},
    markRead(token,id){const user=actor(token);const result=db.prepare('UPDATE notifications SET read_at=COALESCE(read_at,?) WHERE id=? AND user_id=?').run(now(),id,user.id);if(!result.changes)throw new Error('Notification not found.');return true},
  }
  const resources={
    list(token){const user=actor(token,'resources.read');let scope='';const params=[];if(user.roles.includes('Teacher')){scope=' WHERE r.class_arm_id IS NULL OR r.class_arm_id IN (SELECT ta.class_arm_id FROM teacher_assignments ta JOIN staff s ON s.id=ta.staff_id WHERE s.user_id=?)';params.push(user.id)}if(user.roles.includes('Parent')){scope=' WHERE r.class_arm_id IS NULL OR r.class_arm_id IN (SELECT st.class_arm_id FROM students st JOIN student_parents sp ON sp.student_id=st.id JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=?)';params.push(user.id)}if(user.roles.includes('Student')){scope=' WHERE r.class_arm_id IS NULL OR r.class_arm_id=(SELECT s.class_arm_id FROM students s JOIN student_portal_link l ON l.student_id=s.id WHERE l.user_id=?)';params.push(user.id)}return db.prepare(`SELECT r.id,r.title,r.description,r.resource_type,r.original_name,r.mime_type,r.size_bytes,r.class_arm_id,r.created_at FROM resources r${scope} ORDER BY r.created_at DESC`).all(...params)},
    upload(token,source,input){const user=actor(token,'resources.manage');if(!source||!path.isAbsolute(source)||!fs.existsSync(source))throw new Error('Choose a file that exists on this device.');const info=fs.statSync(source);if(info.size>100*1024*1024)throw new Error('Resource files must be 100 MB or smaller.');const original=path.basename(source),extension=path.extname(original).toLowerCase();const allowed={'.pdf':'application/pdf','.docx':'application/vnd.openxmlformats-officedocument.wordprocessingml.document','.pptx':'application/vnd.openxmlformats-officedocument.presentationml.presentation','.xlsx':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','.jpg':'image/jpeg','.jpeg':'image/jpeg','.png':'image/png','.txt':'text/plain'};if(!allowed[extension])throw new Error('Choose PDF, Word, PowerPoint, Excel, JPG, PNG, or text files.');if(user.roles.includes('Teacher')&&input.classArmId&&!db.prepare('SELECT 1 FROM teacher_assignments ta JOIN staff s ON s.id=ta.staff_id WHERE s.user_id=? AND ta.class_arm_id=?').get(user.id,Number(input.classArmId)))throw new Error('Teachers may upload only to their assigned classes.');const directory=path.join(app.getPath('userData'),'resources');fs.mkdirSync(directory,{recursive:true});const stored=path.join(directory,`${uuid()}${extension}`);fs.copyFileSync(source,stored);const id=uuid();db.prepare('INSERT INTO resources(id,title,description,resource_type,stored_path,original_name,mime_type,size_bytes,uploaded_by,class_arm_id) VALUES(?,?,?,?,?,?,?,?,?,?)').run(id,text(input.title||path.parse(original).name,'Resource title',180),input.description||null,['Assignment','Lesson note','Learning material'].includes(input.resourceType)?input.resourceType:'Learning material',stored,original,allowed[extension],info.size,user.id,input.classArmId?Number(input.classArmId):null);audit(user.id,'resource_uploaded','resources',id);return{id,originalName:original}},
    metadata(token,id){const user=actor(token,'resources.read');const row=db.prepare('SELECT * FROM resources WHERE id=?').get(id);if(!row)throw new Error('Resource not found.');if(row.class_arm_id&&user.roles.includes('Teacher')&&!db.prepare('SELECT 1 FROM teacher_assignments ta JOIN staff s ON s.id=ta.staff_id WHERE s.user_id=? AND ta.class_arm_id=?').get(user.id,row.class_arm_id))throw new Error('This resource is outside your assigned classes.');if(row.class_arm_id&&user.roles.includes('Parent')&&!db.prepare('SELECT 1 FROM students s JOIN student_parents sp ON sp.student_id=s.id JOIN parents p ON p.id=sp.parent_id WHERE p.user_id=? AND s.class_arm_id=?').get(user.id,row.class_arm_id))throw new Error('This resource is not assigned to your children.');if(row.class_arm_id&&user.roles.includes('Student')&&!db.prepare('SELECT 1 FROM students s JOIN student_portal_link l ON l.student_id=s.id WHERE l.user_id=? AND s.class_arm_id=?').get(user.id,row.class_arm_id))throw new Error('This resource is not assigned to your class.');return row},
    read(token,id){const row=resources.metadata(token,id);return{filename:row.original_name,mimeType:row.mime_type,data:fs.readFileSync(row.stored_path).toString('base64')}},
  }
  const reports={
    studentRegister(token,filter={}){actor(token,'reports.read');return students.list(token,{...filter,limit:1000})},
    financial(token,filter={}){actor(token,'reports.read');return finance.outstanding(token,filter)},
    data(token,kind,filter={}){const user=actor(token,'reports.read');if(kind==='students')return reports.studentRegister(token,filter);if(kind==='outstanding')return reports.financial(token,filter);if(kind==='payments')return finance.payments(token,filter);if(kind==='expenses')return finance.expenses(token);if(kind==='collections'){actor(token,'finance.read');const term=filter.termId?db.prepare('SELECT id,session_id FROM terms WHERE id=?').get(Number(filter.termId)):db.prepare('SELECT id,session_id FROM terms WHERE active=1 LIMIT 1').get();if(!term)return[];return db.prepare("SELECT date(p.paid_at) date,p.method,COUNT(*) payment_count,SUM(p.amount_kobo)/100 amount FROM payments p WHERE p.status='Verified' AND p.session_id=? AND p.term_id=? GROUP BY date(p.paid_at),p.method ORDER BY date(p.paid_at)").all(term.session_id,term.id)}if(kind==='attendance'){if(!user.permissions.includes('attendance.read')&&!user.permissions.includes('school.manage'))throw new Error('Attendance reports are restricted.');return db.prepare("SELECT a.attendance_date,s.admission_number,s.first_name||' '||s.surname student_name,c.name class_name,arm.name arm_name,a.status,a.note FROM attendance a JOIN students s ON s.id=a.student_id JOIN class_arms arm ON arm.id=a.class_arm_id JOIN classes c ON c.id=arm.class_id WHERE (? IS NULL OR a.attendance_date=?) ORDER BY a.attendance_date DESC,c.sort_order,s.surname").all(filter.date||null,filter.date||null)}if(kind==='results'){if(!user.permissions.includes('academics.read')&&!user.permissions.includes('school.manage'))throw new Error('Academic reports are restricted.');return db.prepare("SELECT se.name session_name,t.name term_name,s.admission_number,s.first_name||' '||s.surname student_name,c.name class_name,sub.name subject,ac.name component,r.score,ac.max_score,r.status FROM results r JOIN students s ON s.id=r.student_id JOIN subjects sub ON sub.id=r.subject_id JOIN assessment_components ac ON ac.id=r.component_id JOIN terms t ON t.id=ac.term_id JOIN academic_sessions se ON se.id=ac.session_id JOIN class_arms arm ON arm.id=s.class_arm_id JOIN classes c ON c.id=arm.class_id ORDER BY se.starts_on DESC,t.id,c.sort_order,s.surname,sub.name").all()}if(kind==='staff'||kind==='parents'){if(!user.permissions.includes('school.manage'))throw new Error('Staff and parent registers are restricted to school administrators.');if(kind==='staff')return db.prepare('SELECT staff_number,first_name,surname,kind,phone,email,hired_on,active FROM staff ORDER BY kind,surname,first_name').all();return db.prepare("SELECT p.first_name,p.surname,p.phone,p.email,p.address,COUNT(sp.student_id) children FROM parents p LEFT JOIN student_parents sp ON sp.parent_id=p.id GROUP BY p.id ORDER BY p.surname,p.first_name").all()}if(kind==='stakeholders'){if(!user.permissions.includes('stakeholders.read'))throw new Error('Stakeholder reports are restricted.');return db.prepare('SELECT ss.name,ss.representative,ss.phone,ss.email,ss.status,r.first_name student_first_name,r.surname student_surname,r.status application_status,r.assigned_admission_number,r.created_at FROM stakeholder_schools ss LEFT JOIN stakeholder_registrations r ON r.stakeholder_id=ss.id ORDER BY ss.name,r.created_at DESC').all()}if(kind==='audit'){if(!user.permissions.includes('school.manage'))throw new Error('Only school administrators can access the full audit log.');return db.prepare('SELECT a.*,u.username actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.id DESC LIMIT 5000').all().map(x=>({...x,details:JSON.parse(x.details_json)}))}throw new Error('Unknown report type.')},
  }
  const calendar={
    list(token){actor(token,'dashboard.read');return{events:db.prepare('SELECT * FROM school_events ORDER BY starts_at').all(),timetable:db.prepare('SELECT te.*,c.name class_name,a.name arm_name,s.name subject,st.first_name||\' \'||st.surname teacher_name FROM timetable_entries te JOIN class_arms a ON a.id=te.class_arm_id JOIN classes c ON c.id=a.class_id JOIN subjects s ON s.id=te.subject_id LEFT JOIN staff st ON st.id=te.staff_id ORDER BY te.weekday,te.starts_at').all()}},
    addEvent(token,input){const user=actor(token,'school.manage');const id=Number(db.prepare('INSERT INTO school_events(title,description,starts_at,ends_at,location) VALUES(?,?,?,?,?)').run(text(input.title,'Event title',120),input.description||null,text(input.startsAt,'Start time',40),input.endsAt||null,input.location||null).lastInsertRowid);audit(user.id,'school_event_created','school_events',id);return{id}},
    addTimetable(token,input){const user=actor(token,'school.manage');const day=Number(input.weekday),start=text(input.startsAt,'Start time',8),end=text(input.endsAt,'End time',8);if(day<1||day>5||start>=end)throw new Error('Choose a weekday and a valid time range.');const id=Number(db.prepare('INSERT INTO timetable_entries(class_arm_id,subject_id,staff_id,weekday,starts_at,ends_at,room) VALUES(?,?,?,?,?,?,?)').run(Number(input.classArmId),Number(input.subjectId),input.staffId||null,day,start,end,input.room||null).lastInsertRowid);audit(user.id,'timetable_entry_created','timetable_entries',id);return{id}},
  }
  const backups={
    create(token,target){const user=actor(token,'backups.manage');if(!target||!path.isAbsolute(target))throw new Error('Choose an absolute backup file path.');if(fs.existsSync(target))throw new Error('A file already exists at that path; choose a new backup name.');const temp=`${target}.${uuid()}.tmp`;db.pragma('wal_checkpoint(FULL)');fs.copyFileSync(db.name,temp);try{const check=new (require('better-sqlite3'))(temp,{readonly:true,fileMustExist:true});const integrity=check.pragma('integrity_check',{simple:true});check.close();if(integrity!=='ok')throw new Error('Backup verification failed.');fs.renameSync(temp,target)}catch(e){if(fs.existsSync(temp))fs.unlinkSync(temp);throw e}const digest=crypto.createHash('sha256').update(fs.readFileSync(target)).digest('hex');const stats=fs.statSync(target);const backupId=Number(db.prepare('INSERT INTO backup_history(file_path,size_bytes,checksum,created_by,verified) VALUES(?,?,?,?,1)').run(target,stats.size,digest,user.id).lastInsertRowid);audit(user.id,'database_backup_created','backup_history',backupId,{checksum:digest});return{backupId,filePath:target,bytes:stats.size,checksum:digest}},
    restore(token,source){const user=actor(token,'backups.manage');if(!source||!path.isAbsolute(source)||!fs.existsSync(source))throw new Error('Choose an existing backup file.');const live=db.name;if(path.resolve(source)===path.resolve(live))throw new Error('Choose a backup file instead of the active school database.');const check=new (require('better-sqlite3'))(source,{readonly:true,fileMustExist:true});const integrity=check.pragma('integrity_check',{simple:true});check.close();if(integrity!=='ok')throw new Error('Backup verification failed; restore was stopped.');const safety=`${live}.pre-restore-${Date.now()}`;audit(user.id,'database_restored','backup_history',null,{source});db.pragma('wal_checkpoint(FULL)');db.close();fs.copyFileSync(live,safety);fs.copyFileSync(source,live);app.relaunch();app.exit(0);return true},
  }
  const paymentReceipts = require('./payment-receipts.cjs').createPaymentReceipts(db,app,actor,audit)
  return{auth,school,dashboard,students,classes,users,finance,academics,attendance,stakeholders,communication,resources,reports,calendar,backups,paymentReceipts}
}
module.exports={createServices}
